import { Agent, GameEngine } from "../game";
import { MovementType, AnimState } from "../../types";
import { HexUtils } from "../utils";
import { PHYSICS } from "../../constants";

export class PhysicsEngine {
    public static applyImpulse(target: Agent, origin: {x: number, y: number}, force: number, randomness: number = 0) {
        const dx = target.px - origin.x;
        const dy = target.py - origin.y;
        const len = Math.sqrt(dx * dx + dy * dy);
        const effectiveForce = Math.min(PHYSICS.TERMINAL_VELOCITY_IMPULSE, Math.max(50, force));
        let vx = 0, vy = 0;
        if (len <= 0.1) {
            const ang = Math.random() * Math.PI * 2;
            vx = Math.cos(ang) * effectiveForce;
            vy = Math.sin(ang) * effectiveForce;
        } else {
            vx = (dx / len) * effectiveForce;
            vy = (dy / len) * effectiveForce;
        }
        target.physics.vx += vx;
        target.physics.vy += vy;

        // TA: 擊退時增加隨機旋轉，製造失衡感
        target.physics.vAngle += (Math.random() - 0.5) * 10.0; 

        if (randomness > 0) target.physics.vAngle += (Math.random() - 0.5) * randomness;
    }

    public update(a: Agent, dt: number, engine: GameEngine) {
        if (a.fullyDead) return;
        const isDead = a.hp <= 0;

        // TA 優化：增加 Stiffness 使受擊後恢復更迅速
        const stiffness = isDead ? 0 : PHYSICS.STIFFNESS_ALIVE * 1.2;
        const damping = PHYSICS.DAMPING_ALIVE * 1.1; 

        const fx = -stiffness * a.physics.x;
        const fy = -stiffness * a.physics.y;
        const fRot = -stiffness * a.physics.angle * 0.1; 

        const ax = fx - damping * a.physics.vx;
        const ay = fy - damping * a.physics.vy;
        const aRot = fRot - damping * a.physics.vAngle;

        a.physics.vx += ax * dt;
        a.physics.vy += ay * dt;
        a.physics.vAngle += aRot * dt;

        const isAirborne = a.physics.z > 0;
        const isFlying = a.movementType === MovementType.FLYING && !isDead;
        const isDisabled = a.stunTimer > 0 || a.visualStatus === 'FROZEN' || a.visualStatus === 'POLYMORPH';

        // 核心物理更新
        if (isFlying && !isDisabled) {
            const hoverHeight = 55, hoverFreq = 2.5; 
            const targetZ = hoverHeight + Math.sin(engine.battleTime * hoverFreq) * 5;
            const dz = targetZ - a.physics.z;
            a.physics.vz += dz * 5 * dt;
            a.physics.vz *= 0.92;
        } else if (isAirborne || a.physics.z > 0.1) {
            a.physics.vz -= PHYSICS.GRAVITY * dt;
        }

        a.physics.x += a.physics.vx * dt;
        a.physics.y += a.physics.vy * dt;
        a.physics.z += a.physics.vz * dt;
        a.physics.angle += a.physics.vAngle * dt;

        // 紀錄高速軌跡 (用於繪製殘影/拖尾)
        // 速度 > 100 且未完全靜止時記錄
        const speedSq = a.physics.vx*a.physics.vx + a.physics.vy*a.physics.vy;
        if (speedSq > 10000 || (a.movementType === MovementType.FLYING && a.hp > 0)) {
            a.trailHistory.push({ x: a.px + a.physics.x, y: a.py + a.physics.y, z: a.physics.z });
            if (a.trailHistory.length > 10) a.trailHistory.shift();
        } else if (a.trailHistory.length > 0) {
            // 速度慢下來後慢慢清除軌跡
            a.trailHistory.shift();
        }

        // 著地判定
        if (a.physics.z < 0) {
            a.physics.z = 0;
            if (a.physics.vz < -PHYSICS.SAFE_FALL_VELOCITY) {
                const impactSpeed = Math.abs(a.physics.vz);
                if (!isDead) {
                    const velocityOverhead = impactSpeed - PHYSICS.SAFE_FALL_VELOCITY;
                    const scaling = PHYSICS.FATAL_FALL_VELOCITY - PHYSICS.SAFE_FALL_VELOCITY;
                    const pct = Math.min(1.0, velocityOverhead / scaling);
                    const rawDmg = Math.floor(a.maxHp * pct) + PHYSICS.FALL_DAMAGE_MIN;
                    a.hp = Math.max(0, a.hp - rawDmg);
                    engine.events.push({ type: 'DAMAGE', pos: {x: a.px, y: a.py}, value: -rawDmg, color: '#ef4444', text: "墜落" });
                    engine.log(a, 'HAZARD', '墜落', '地面', `受到墜落傷害 ${rawDmg}`);

                    engine.bus.emit('CAMERA_SHAKE', { intensity: pct * 0.5 });

                    if (a.hp <= 0) engine.agentManager.handleDeadState(a, engine);
                    else a.setAnim(AnimState.HIT);
                }
                a.physics.vz = -a.physics.vz * 0.3;
                a.physics.vx *= 0.5; a.physics.vy *= 0.5; a.physics.vAngle *= 0.5;
            } else {
                a.physics.vz = 0;
            }
        }

        // 漂移回歸 (Drift Back to Logical Position)
        if (!isDead && !a.isMoving) {
            const targetPos = HexUtils.toPx(a.q, a.r, engine.mapConfig);
            const dx = targetPos.x - a.px, dy = targetPos.y - a.py;
            const distSq = dx*dx + dy*dy;

            // 只有在受力很小的時候才啟用漂移，避免與擊退力對抗
            if (speedSq < 5000) {
                if (distSq > 0.5) {
                    const driftSpeed = PHYSICS.DRIFT_SPEED * dt; 
                    a.px += dx * driftSpeed; a.py += dy * driftSpeed;
                    if (distSq < 2) { a.px = targetPos.x; a.py = targetPos.y; }
                } else {
                    a.px = targetPos.x; a.py = targetPos.y;
                }
            }
        }
    }
}

import { Agent, GameEngine } from "../game";
import { PhysicsEngine } from "../physics/PhysicsEngine";
import { MovementType } from "../../types";

export class PhysicsSystem {
    private engine: PhysicsEngine;
    private dustTimer: number = 0;

    constructor() {
        this.engine = new PhysicsEngine();
    }

    public update(dt: number, engine: GameEngine) {
        this.dustTimer += dt;
        const canSpawnDust = this.dustTimer > 0.05; // Limit dust rate (20fps)

        for (const a of engine.agents) {
            // Apply Physics Integration
            this.engine.update(a, dt, engine);

            // VFX: Automatic Friction Dust / Sparks
            // 如果單位在地面且速度極快 (擊退或突進)
            if (canSpawnDust && engine.renderer && a.hp > 0) {
                const speedSq = a.physics.vx*a.physics.vx + a.physics.vy*a.physics.vy;
                const isGrounded = a.physics.z < 5;
                const isFlyingUnit = a.movementType === MovementType.FLYING;

                // 速度門檻：300px/s (約正常移動速度的 3 倍，或受擊時)
                if (speedSq > 90000 && isGrounded && !isFlyingUnit) {

                    // 根據速度決定粒子類型
                    const type = speedSq > 250000 ? 'SPARK' : 'DUST'; // 極快時出火花
                    const color = type === 'SPARK' ? '#fbbf24' : '#78716c';

                    // 在腳底生成粒子
                    const terrainH = engine.map.getTerrainHeight(a.q, a.r);
                    engine.renderer.vfx.playEffect(
                        type === 'SPARK' ? 'FX_STATUS_STUN_LOOP' : 'FX_STATUS_ROOT_LOOP', // 重用現有的小型粒子
                        a.px + a.physics.x, 
                        a.py + a.physics.y, 
                        terrainH + 5
                    );
                }
            }
        }

        if (canSpawnDust) this.dustTimer = 0;
    }
}

import { Agent } from "../../../../game";
import { Team, AnimState, MovementType } from "../../../../../types";
import { UNIT_SCALE } from "../../../../../constants";
import { ImperialRenderer } from "../factions/ImperialRenderer";
import { CovenantRenderer } from "../factions/CovenantRenderer";
import { UnitFlightPainter } from "./UnitFlightPainter";
import { SpriteManager } from "../../../sprites";
import { VisualMath } from "../../../math/VisualMath";

export const UnitBodyPainter = {
    draw(
        ctx: CanvasRenderingContext2D, 
        agent: Agent, 
        px: number, py: number, 
        t: number, 
        isSilhouette: boolean, 
        isSelected: boolean,
        scaleFactor: number
    ) {
        // --- 1. 計算物理動態參數 (Juice Math) ---
        const vx = agent.physics.vx;
        const vy = agent.physics.vy;
        const speedSq = vx*vx + vy*vy;

        // 傾斜邏輯：
        // 如果是突進 (主動移動)，身體向前傾 (Tilt Forward)
        // 如果是擊退 (受力且無主動意圖)，身體向後仰 (Tilt Backward)
        // Facing: 1 (Right), -1 (Left)

        let tiltAngle = 0;
        let isHighSpeed = false;

        if (speedSq > 1000) { // 顯著移動
            const speed = Math.sqrt(speedSq);
            isHighSpeed = speed > 300;

            // 計算移動方向與面向的點積，判斷是前進還是後退
            const dirX = vx / speed;
            const dot = dirX * agent.facing; 

            // 基礎傾斜量 (最大 30度)
            const maxTilt = 0.5; 
            let tiltFactor = Math.min(1.0, speed / 800) * maxTilt;

            // 突進(同向): 前傾 (+)
            // 擊退(反向): 後仰 (-)
            // 注意：Canvas 旋轉是順時針為正。
            // 面向右 (Facing=1): 前傾是順時針 (+), 後仰是逆時針 (-)
            // 面向左 (Facing=-1): 前傾是逆時針 (-), 後仰是順時針 (+)

            if (dot > 0) {
                // Moving Forward -> Lean Forward
                tiltAngle = tiltFactor * agent.facing;
            } else {
                // Moving Backward -> Lean Backward (Get knocked back)
                // 擊退時增加更多旋轉，製造失衡感
                tiltAngle = -tiltFactor * agent.facing * 1.5; 
            }
        }

        // 疊加物理引擎的隨機旋轉 (Impact Trauma)
        const finalRotation = agent.physics.angle + tiltAngle;

        // --- 2. 殘影繪製 (Ghosting) ---
        // 僅在高速移動且非剪影模式下繪製
        if (isHighSpeed && !isSilhouette && agent.hp > 0) {
            const history = agent.trailHistory;
            // 每隔 2 幀畫一個殘影，最多畫 2 個，避免過於雜亂
            const step = 2;
            const maxGhosts = 2;

            for (let i = Math.max(0, history.length - 1 - (maxGhosts*step)); i < history.length - 1; i += step) {
                const pos = history[i];
                // 透明度隨時間遞減
                const opacity = (i / history.length) * 0.3; 

                ctx.save();
                // 使用殘影位置進行變換
                // 注意：這裡需要重新計算殘影的 Visual Y (包含 Z 軸)
                const ghostY = VisualMath.getVisualBodyCenterY(pos.y, pos.z);

                ctx.translate(pos.x, ghostY);
                ctx.scale(UNIT_SCALE, UNIT_SCALE);
                ctx.rotate(finalRotation * 0.5); // 殘影旋轉稍微滯後
                ctx.scale(agent.facing > 0 ? 1 : -1, 1);

                ctx.globalAlpha = opacity;
                ctx.globalCompositeOperation = 'screen'; // 殘影使用濾色模式，像能量留存

                // 根據陣營繪製單色剪影
                const color = agent.team === Team.BLUE ? '#60a5fa' : '#ef4444';

                // 這裡簡化繪製：只畫通用形狀或調用 faction renderer 但強制單色
                // 為了效能，我們畫一個簡單的 Unit Shape 填充
                ctx.fillStyle = color;
                ctx.beginPath();
                ctx.moveTo(-10, -40); ctx.lineTo(10, -40);
                ctx.lineTo(5, 10); ctx.lineTo(-5, 10);
                ctx.fill();

                ctx.restore();
            }
        }

        // --- 3. 主體渲染 ---
        ctx.save(); 

        // 獲取身體中心視覺 Y 軸 (SSOT)
        const pz = agent.physics.z;
        const bodyY = VisualMath.getVisualBodyCenterY(py, pz);
        ctx.translate(px, bodyY); 

        // 核心受擊幾何處理 (Juice Math)
        let hitBrightness = 0;
        let squashX = 1.0;
        let squashY = 1.0;

        if (agent.hitFlashTimer > 0 && !isSilhouette) {
            const trauma = agent.hitFlashTimer / 0.2; 
            squashY = 1.0 - (trauma * 0.25);
            squashX = 1.0 + (trauma * 0.15);
            hitBrightness = 100 + Math.sin(t * 40) * 50;
        }

        ctx.scale(UNIT_SCALE * squashX, UNIT_SCALE * squashY);
        ctx.rotate(finalRotation); // 應用計算出的動態傾斜

        // 基礎呼吸與浮動
        let bodyFloat = 0; 
        if (agent.hp > 0 && agent.movementType !== MovementType.FLYING) {
             bodyFloat = Math.sin(t * 2) * 3; 
        } else if (agent.movementType === MovementType.FLYING) {
             bodyFloat = Math.sin(t * 4) * 2;
        }
        ctx.translate(0, bodyFloat);

        // 進場縮放動畫
        if (agent.spawnTimer > 0) {
            const SPAWN_DURATION = 0.5; 
            const progress = 1 - (agent.spawnTimer / SPAWN_DURATION); 
            const eased = 1 - Math.pow(1 - progress, 3); 
            ctx.scale(1, 2.0 - eased); 
            ctx.globalAlpha *= eased;
        }

        // 狀態濾鏡應用
        if (agent.hp <= 0 && !isSilhouette) {
            ctx.filter = 'grayscale(100%) opacity(70%)'; 
        } else if (hitBrightness > 0) {
             ctx.filter = `brightness(${hitBrightness}%) contrast(120%)`;
        }

        // 飛行與拖尾渲染 (包含地面的滑行痕跡)
        // 只要有速度或是在飛，就嘗試畫軌跡
        if (agent.hp > 0 && !isSilhouette && agent.visualStatus === 'NONE') {
            if (agent.movementType === MovementType.FLYING || speedSq > 5000) {
                UnitFlightPainter.drawRibbonTrail(ctx, agent, t);
            }
            if (agent.movementType === MovementType.FLYING) {
                UnitFlightPainter.drawFlightVFX(ctx, agent, t);
            }
        }

        ctx.scale(agent.facing > 0 ? 1 : -1, 1);

        if (agent.visualStatus === 'POLYMORPH' && !isSilhouette) {
            const sheep = SpriteManager.getSpecialModel('SHEEP');
            const bounce = Math.abs(Math.sin(t * 5) * 5);
            ctx.drawImage(sheep, -32, -32 - bounce, 64, 64);
        } else {
            if (agent.team === Team.BLUE) {
                ImperialRenderer.draw(ctx, agent, t, isSilhouette);
            } else {
                CovenantRenderer.draw(ctx, agent, t, isSilhouette);
            }

            if (agent.visualStatus === 'FROZEN' && !isSilhouette) {
                const ice = SpriteManager.getSpecialModel('ICE');
                ctx.save();
                ctx.globalCompositeOperation = 'hard-light';
                ctx.drawImage(ice, -48, -64, 96, 128);
                ctx.restore();
            }
        }

        ctx.restore(); 
    }
};

import { Agent } from "../../../game";
import { Team, MovementType } from "../../../../types";
import { UNIT_SCALE, VISUAL_ANCHORS } from "../../../../constants";
import { FACTION_VISUALS } from "../../../../data/vfx/faction_visuals";
import { VisualMath } from "../../../math/VisualMath";

export const UnitFlightPainter = {

    drawFlyingAnchor(ctx: CanvasRenderingContext2D, agent: Agent, t: number, physX: number, physY: number, physZ: number) {
        // Deprecated
    },

    drawFlightVFX(ctx: CanvasRenderingContext2D, agent: Agent, t: number) {
        // This is called within the UnitBodyPainter's transformed context (Body Center)
        const faction = FACTION_VISUALS[agent.team] || FACTION_VISUALS[Team.BLUE];
        const color = faction.flightTrailColor;

        ctx.save();
        ctx.translate(0, VISUAL_ANCHORS.ENGINE_OFFSET_Y); // Use Standard Constant

        // Engine Glows (Oscillating)
        const pulse = 0.8 + Math.sin(t * 20) * 0.2;

        ctx.globalCompositeOperation = 'screen';
        ctx.fillStyle = color;
        ctx.shadowColor = color;
        ctx.shadowBlur = 10;

        // Left Engine
        ctx.beginPath(); ctx.arc(-12, 0, 4 * pulse, 0, Math.PI*2); ctx.fill();
        // Right Engine
        ctx.beginPath(); ctx.arc(12, 0, 4 * pulse, 0, Math.PI*2); ctx.fill();

        ctx.restore();
    },

    /**
     * 通用軌跡繪製：支持飛行緞帶 (Ribbon) 與地面滑痕 (Skid Marks)
     */
    drawRibbonTrail(ctx: CanvasRenderingContext2D, agent: Agent, t: number) {
        if (agent.trailHistory.length < 2) return;

        const faction = FACTION_VISUALS[agent.team] || FACTION_VISUALS[Team.BLUE];
        const color = faction.flightTrailColor;
        const isFlying = agent.movementType === MovementType.FLYING;

        ctx.save();
        ctx.lineCap = 'round';
        ctx.lineJoin = 'round';

        const currentPx = agent.px;
        const currentPy = agent.py; // Ground Y (Logical)

        const points: {x: number, y: number}[] = [];

        // 轉換軌跡點到視覺座標系
        for (const p of agent.trailHistory) {
            // Reconstruct visual Y using SSOT Math
            const vy = VisualMath.getVisualBodyCenterY(p.y, p.z) + VISUAL_ANCHORS.ENGINE_OFFSET_Y;
            points.push({ x: p.x, y: vy });
        }

        // Add current pos
        const currVy = VisualMath.getVisualBodyCenterY(currentPy, agent.physics.z) + VISUAL_ANCHORS.ENGINE_OFFSET_Y;
        points.push({ x: currentPx, y: currVy });

        if (points.length < 2) { ctx.restore(); return; }

        ctx.beginPath();

        for (let i = 0; i < points.length; i++) {
            const p = points[i];
            const dx = p.x - currentPx;
            const dy = p.y - currVy;

            // Draw relative to Engine Offset
            const engineY = VISUAL_ANCHORS.ENGINE_OFFSET_Y;

            if (i === 0) ctx.moveTo(dx, engineY + dy);
            else ctx.lineTo(dx, engineY + dy);
        }

        if (isFlying) {
            // 飛行模式：柔和的光帶
            ctx.strokeStyle = color;
            ctx.lineWidth = 4 * UNIT_SCALE;
            ctx.globalAlpha = 0.4;
            ctx.shadowColor = color;
            ctx.shadowBlur = 10;
            ctx.stroke();

            // Inner Core
            ctx.strokeStyle = '#fff';
            ctx.lineWidth = 1 * UNIT_SCALE;
            ctx.globalAlpha = 0.8;
            ctx.shadowBlur = 0;
            ctx.stroke();
        } else {
            // 地面模式：銳利的滑行痕跡 (Skid Marks)
            // 模擬摩擦生熱的火光或塵土軌跡
            ctx.strokeStyle = color;
            ctx.lineWidth = 3 * UNIT_SCALE;
            ctx.globalAlpha = 0.3; // 較淡
            ctx.globalCompositeOperation = 'screen';
            ctx.stroke();

            // 如果速度極快，加一點白色核心代表火花
            ctx.strokeStyle = '#fff';
            ctx.lineWidth = 1;
            ctx.setLineDash([5, 5]); // 斷續的刮痕感
            ctx.globalAlpha = 0.5;
            ctx.stroke();
        }

        ctx.restore();
    }
};

