                ctx.lineWidth = 4;
                ctx.lineJoin = 'round';
                ctx.strokeStyle = '#000';
                ctx.strokeText(d.text, 0, 0);
                ctx.fillStyle = grad;
                ctx.fillText(d.text, 0, 0);

            } else if (d.type === 'SHOUT') {
                if (d.isUlt) {
                    // --- ULTIMATE CASTING VISUAL ---
                    const scale = 1 + (1 - lifePct) * 0.1; 
                    ctx.scale(scale, scale);
                    ctx.font = `900 italic ${d.size}px "Arial Black", sans-serif`;
                    const textMetrics = ctx.measureText(d.text);
                    const w = textMetrics.width / 2 + 35; // Wider for cinematic feel
                    const h = d.size + 14;

                    if (d.isShattered) {
                        // ... Shattered Ult (Dark, broken) ...
                        const bgGrad = ctx.createLinearGradient(-w - 20, 0, w + 20, 0);
                        bgGrad.addColorStop(0, 'rgba(0,0,0,0)');
                        bgGrad.addColorStop(0.5, 'rgba(50, 20, 20, 0.4)');
                        bgGrad.addColorStop(1, 'rgba(0,0,0,0)');
                        ctx.fillStyle = bgGrad;
                        ctx.fillRect(-w - 20, -h/2, w*2 + 40, h);

                        ctx.fillStyle = '#94a3b8';
                        ctx.fillText(d.text, 0, 0);

                        ctx.strokeStyle = '#ef4444';
                        ctx.lineWidth = 2;
                        ctx.beginPath(); ctx.moveTo(-w, -h/2); ctx.lineTo(0, -h/2); ctx.stroke();
                        ctx.beginPath(); ctx.moveTo(w, h/2); ctx.lineTo(0, h/2); ctx.stroke();
                    } else {
                        // ... Active Ult (Energy Filling) ...

                        // 1. Cinematic Bar Background
                        const bgGrad = ctx.createLinearGradient(-w - 40, 0, w + 40, 0);
                        bgGrad.addColorStop(0, 'transparent');
                        bgGrad.addColorStop(0.2, 'rgba(0,0,0,0.8)'); 
                        bgGrad.addColorStop(0.8, 'rgba(0,0,0,0.8)');
                        bgGrad.addColorStop(1, 'transparent');
                        ctx.fillStyle = bgGrad;
                        ctx.fillRect(-w - 40, -h/2 - 4, w*2 + 80, h + 8);

                        // 2. Glowing Borders
                        const pulse = 0.5 + Math.sin(d.time * 10) * 0.5;
                        ctx.strokeStyle = d.color;
                        ctx.lineWidth = 1 + pulse;
                        ctx.shadowColor = d.color;
                        ctx.shadowBlur = 10 * pulse;

                        ctx.beginPath();
                        ctx.moveTo(-w - 10, -h/2); ctx.lineTo(w + 10, -h/2);
                        ctx.moveTo(-w - 10, h/2); ctx.lineTo(w + 10, h/2);
                        ctx.stroke();
                        ctx.shadowBlur = 0; 

                        // 3. Brackets
                        ctx.fillStyle = d.color;
                        ctx.font = `20px sans-serif`;
                        ctx.fillText("✦", -w - 20 - (pulse * 2), 1);
                        ctx.fillText("✦", w + 20 + (pulse * 2), 1);

                        // 4. TEXT FILLING LOGIC
                        ctx.font = `900 italic ${d.size}px "Arial Black", sans-serif`;

                        // A. Draw Empty Text (Dim)
                        ctx.fillStyle = 'rgba(255,255,255,0.2)';
                        ctx.fillText(d.text, 0, 0);

                        // B. Calculate Fill Progress
                        // time is elapsed, totalDuration is total cast time.
                        const progress = Math.min(1.0, d.time / d.totalDuration);
                        const fillWidth = (w * 2 - 20) * progress; // Approximate text width coverage
                        const startX = -w + 10;

                        // C. Draw Filled Text (Bright) with Clipping
                        ctx.save();
                        ctx.beginPath();
                        // Define clipping rectangle from Left to Right based on progress
                        ctx.rect(startX, -h, fillWidth, h*2);
                        ctx.clip();

                        // Gradient Text
                        const textGrad = ctx.createLinearGradient(0, -h/2, 0, h/2);
                        textGrad.addColorStop(0, '#ffffff');
                        textGrad.addColorStop(0.5, d.color);
                        textGrad.addColorStop(1, d.color);

                        ctx.shadowColor = d.color;
                        ctx.shadowBlur = 15;
                        ctx.fillStyle = textGrad;
                        ctx.fillText(d.text, 0, 0);

                        // Draw "Energy Edge" line
                        if (progress < 1.0) {
                            ctx.shadowBlur = 5;
                            ctx.shadowColor = '#fff';
                            ctx.fillStyle = '#fff';
                            const edgeX = startX + fillWidth;
                            // Draw a thin vertical glow line at the edge
                            ctx.fillRect(edgeX - 1, -h/2, 2, h);
                        }

                        ctx.restore();
                    }

                } else {
                    // --- NORMAL CAST VISUAL ---
                    ctx.font = `bold ${d.size}px "Segoe UI", sans-serif`;
                    const textMetrics = ctx.measureText(d.text);
                    const padX = 14;
                    const padY = 8;
                    const w = textMetrics.width;
                    const h = d.size;

                    if (d.isShattered) {
                        ctx.fillStyle = 'rgba(30, 30, 30, 0.4)'; 
                        ctx.beginPath();
                        if (ctx.roundRect) ctx.roundRect(-w/2 - padX, -h/2 - padY, w + padX*2, h + padY*2, 8);
                        else ctx.rect(-w/2 - padX, -h/2 - padY, w + padX*2, h + padY*2);
                        ctx.fill();
                        ctx.strokeStyle = 'rgba(255,50,50,0.1)';
                        ctx.lineWidth = 1;
                        ctx.stroke();
                        ctx.fillStyle = '#94a3b8'; 
                        ctx.fillText(d.text, 0, 0);
                    } else {
                        // Magic Box Background
                        ctx.fillStyle = 'rgba(15, 23, 42, 0.85)';

                        // Border
                        const pulse = 0.5 + Math.sin(d.time * 8) * 0.5;
                        ctx.strokeStyle = d.color;
                        ctx.shadowColor = d.color;
                        ctx.shadowBlur = 5 + pulse * 5;
                        ctx.lineWidth = 1.5;

                        ctx.beginPath();
                        if (ctx.roundRect) ctx.roundRect(-w/2 - padX, -h/2 - padY, w + padX*2, h + padY*2, 6);
                        else ctx.rect(-w/2 - padX, -h/2 - padY, w + padX*2, h + padY*2);
                        ctx.fill();
                        ctx.stroke();
                        ctx.shadowBlur = 0;

                        // FILLING TEXT LOGIC
                        // A. Empty Text
                        ctx.fillStyle = 'rgba(255,255,255,0.3)'; 
                        ctx.fillText(d.text, 0, 0);

                        // B. Filled Text (Masked)
                        const progress = Math.min(1.0, d.time / d.totalDuration);
                        const boxW = w + padX*2;
                        const fillW = boxW * progress;
                        const startX = -boxW/2;

                        ctx.save();
                        ctx.beginPath();
                        ctx.rect(startX, -h, fillW, h*2);
                        ctx.clip();

                        ctx.shadowColor = d.color;
                        ctx.shadowBlur = 8;
                        ctx.fillStyle = '#ffffff'; // Bright filled text
                        ctx.fillText(d.text, 0, 0);

                        // Edge Glint
                        if (progress < 1.0) {
                            ctx.fillStyle = '#ffffff';
                            ctx.shadowBlur = 10;
                            ctx.fillRect(startX + fillW - 2, -h, 2, h*2);
                        }

                        ctx.restore();
                    }
                }

            } else {
                // DAMAGE / HEAL / CC
                ctx.font = `900 ${d.size}px "Segoe UI", sans-serif`;

                // Outline to make it readable on any background
                ctx.lineWidth = 3;
                ctx.strokeStyle = 'rgba(0,0,0,0.8)';
                ctx.strokeText(d.text, 0, 0);

                ctx.fillStyle = d.color; 
                ctx.fillText(d.text, 0, 0);
            }

            ctx.restore();
            ctx.globalAlpha = 1.0;
        });
    }
};

import { HUDSystem } from "../../systems/hud";

export const TextPainter = {

    drawFloatingText(ctx: CanvasRenderingContext2D, hud: HUDSystem) {
        hud.damageNumbers.forEach(d => {
            if (!d.active) return;

            const lifePct = d.life / d.maxLife;
            // Shattered text fades faster visually
            const alpha = d.isShattered ? lifePct : (lifePct < 0.3 ? lifePct / 0.3 : 1.0);

            // Optimization: Skip invisible text
            if (alpha <= 0.01) return;

            ctx.globalAlpha = alpha;
            ctx.textAlign = 'center';
            ctx.textBaseline = 'middle';
            ctx.shadowBlur = 0; 

            // Save state for rotation transformation if needed
            ctx.save();
            ctx.translate(d.x, d.y);

            // Apply shatter rotation
            if (d.rotation !== 0) ctx.rotate(d.rotation);

            // Apply shatter scale (Explode outwards)
            if (d.isShattered) {
                const shatterProgress = 1 - lifePct;
                const scale = 1.0 + shatterProgress * 0.6; // Scale up to 1.6x
                ctx.scale(scale, scale);
                // Glitch offset for shattered text
                ctx.translate((Math.random()-0.5)*4, (Math.random()-0.5)*4);
            } else if (d.type === 'SHOUT') {
                // Active Shout Float Animation (Magical Levitation)
                const floatY = Math.sin(d.time * 6) * 3;
                ctx.translate(0, floatY);
            }

            if (d.type === 'KILL_STREAK') {
                // (Kill Streak logic remains same)
                const pop = Math.min(1, (1 - lifePct) * 5); 
                const pulse = 1 + Math.sin(lifePct * 10) * 0.1;
                const scale = pop * pulse * 1.5; 
                ctx.scale(scale, scale);
                ctx.font = `900 italic ${d.size}px "Arial Black", sans-serif`;

                const grad = ctx.createLinearGradient(0, -d.size/2, 0, d.size/2);
                grad.addColorStop(0, '#ffffff');
                grad.addColorStop(0.5, d.color);
                grad.addColorStop(1, '#000000');

                ctx.lineWidth = 4;
                ctx.lineJoin = 'round';
                ctx.strokeStyle = '#000';
                ctx.strokeText(d.text, 0, 0);
                ctx.fillStyle = grad;
                ctx.fillText(d.text, 0, 0);

            } else if (d.type === 'SHOUT') {
                // Optimization: Calculate metrics once
                ctx.font = d.isUlt ? `900 italic ${d.size}px "Arial Black", sans-serif` : `bold ${d.size}px "Segoe UI", sans-serif`;
                const textMetrics = ctx.measureText(d.text);
                const w = d.isUlt ? (textMetrics.width / 2 + 35) : textMetrics.width;
                const h = d.size + (d.isUlt ? 14 : 0);

                if (d.isUlt) {
                    // --- ULTIMATE CASTING VISUAL ---
                    const scale = 1 + (1 - lifePct) * 0.1; 
                    ctx.scale(scale, scale);

                    if (d.isShattered) {
                        // [OPTIMIZATION] Simple drawing for shattered state (No Clip, No Gradient)
                        const bgGrad = ctx.createLinearGradient(-w - 20, 0, w + 20, 0);
                        bgGrad.addColorStop(0, 'rgba(0,0,0,0)');
                        bgGrad.addColorStop(0.5, 'rgba(50, 20, 20, 0.4)');
                        bgGrad.addColorStop(1, 'rgba(0,0,0,0)');
                        ctx.fillStyle = bgGrad;
                        ctx.fillRect(-w - 20, -h/2, w*2 + 40, h);

                        ctx.strokeStyle = '#ef4444';
                        ctx.lineWidth = 2;
                        ctx.beginPath(); ctx.moveTo(-w, -h/2); ctx.lineTo(0, -h/2); ctx.stroke();
                        ctx.beginPath(); ctx.moveTo(w, h/2); ctx.lineTo(0, h/2); ctx.stroke();

                        ctx.fillStyle = '#94a3b8';
                        ctx.fillText(d.text, 0, 0);
                    } else {
                        // ... Active Ult (Energy Filling) ...

                        // 1. Cinematic Bar Background
                        const bgGrad = ctx.createLinearGradient(-w - 40, 0, w + 40, 0);
                        bgGrad.addColorStop(0, 'transparent');
                        bgGrad.addColorStop(0.2, 'rgba(0,0,0,0.8)'); 
                        bgGrad.addColorStop(0.8, 'rgba(0,0,0,0.8)');
                        bgGrad.addColorStop(1, 'transparent');
                        ctx.fillStyle = bgGrad;
                        ctx.fillRect(-w - 40, -h/2 - 4, w*2 + 80, h + 8);

                        // 2. Glowing Borders
                        const pulse = 0.5 + Math.sin(d.time * 10) * 0.5;
                        ctx.strokeStyle = d.color;
                        ctx.lineWidth = 1 + pulse;
                        ctx.shadowColor = d.color;
                        ctx.shadowBlur = 10 * pulse;

                        ctx.beginPath();
                        ctx.moveTo(-w - 10, -h/2); ctx.lineTo(w + 10, -h/2);
                        ctx.moveTo(-w - 10, h/2); ctx.lineTo(w + 10, h/2);
                        ctx.stroke();
                        ctx.shadowBlur = 0; 

                        // 3. Brackets
                        ctx.fillStyle = d.color;
                        const bracketFont = `20px sans-serif`;
                        if (ctx.font !== bracketFont) ctx.font = bracketFont;
                        ctx.fillText("✦", -w - 20 - (pulse * 2), 1);
                        ctx.fillText("✦", w + 20 + (pulse * 2), 1);

                        // 4. TEXT FILLING LOGIC
                        ctx.font = `900 italic ${d.size}px "Arial Black", sans-serif`;

                        // Calculate Progress
                        const progress = Math.min(1.0, d.time / d.totalDuration);

                        if (progress >= 1.0) {
                            // [OPTIMIZATION] Full Fill - No Clipping needed
                            ctx.shadowColor = d.color;
                            ctx.shadowBlur = 15;
                            ctx.fillStyle = '#ffffff';
                            ctx.fillText(d.text, 0, 0);
                        } else {
                            // A. Draw Empty Text (Dim)
                            ctx.fillStyle = 'rgba(255,255,255,0.2)';
                            ctx.fillText(d.text, 0, 0);

                            // B. Clipped Fill
                            const fillWidth = (w * 2 - 20) * progress; 
                            const startX = -w + 10;

                            ctx.save();
                            ctx.beginPath();
                            ctx.rect(startX, -h, fillWidth, h*2);
                            ctx.clip(); // Costly operation

                            const textGrad = ctx.createLinearGradient(0, -h/2, 0, h/2);
                            textGrad.addColorStop(0, '#ffffff');
                            textGrad.addColorStop(0.5, d.color);
                            textGrad.addColorStop(1, d.color);

                            ctx.shadowColor = d.color;
                            ctx.shadowBlur = 15;
                            ctx.fillStyle = textGrad;
                            ctx.fillText(d.text, 0, 0);

                            // Energy Edge
                            ctx.shadowBlur = 5;
                            ctx.shadowColor = '#fff';
                            ctx.fillStyle = '#fff';
                            ctx.fillRect(startX + fillWidth - 1, -h/2, 2, h);

                            ctx.restore();
                        }
                    }

                } else {
                    // --- NORMAL CAST VISUAL ---
                    const padX = 14;
                    const padY = 8;
                    // w is full text width for normal cast
                    const boxW = w + padX * 2;
                    const boxH = d.size + padY * 2;

                    if (d.isShattered) {
                        // [OPTIMIZATION] Simple Render
                        ctx.fillStyle = 'rgba(30, 30, 30, 0.4)'; 
                        ctx.beginPath();
                        if (ctx.roundRect) ctx.roundRect(-boxW/2, -boxH/2, boxW, boxH, 8);
                        else ctx.rect(-boxW/2, -boxH/2, boxW, boxH);
                        ctx.fill();

                        ctx.strokeStyle = 'rgba(255,50,50,0.1)';
                        ctx.lineWidth = 1;
                        ctx.stroke();

                        ctx.fillStyle = '#94a3b8'; 
                        ctx.fillText(d.text, 0, 0);
                    } else {
                        // Magic Box Background
                        ctx.fillStyle = 'rgba(15, 23, 42, 0.85)';

                        // Border
                        const pulse = 0.5 + Math.sin(d.time * 8) * 0.5;
                        ctx.strokeStyle = d.color;
                        ctx.shadowColor = d.color;
                        ctx.shadowBlur = 5 + pulse * 5;
                        ctx.lineWidth = 1.5;

                        ctx.beginPath();
                        if (ctx.roundRect) ctx.roundRect(-boxW/2, -boxH/2, boxW, boxH, 6);
                        else ctx.rect(-boxW/2, -boxH/2, boxW, boxH);
                        ctx.fill();
                        ctx.stroke();
                        ctx.shadowBlur = 0;

                        // FILLING TEXT LOGIC
                        const progress = Math.min(1.0, d.time / d.totalDuration);

                        if (progress >= 1.0) {
                            // [OPTIMIZATION] Full text
                            ctx.shadowColor = d.color;
                            ctx.shadowBlur = 8;
                            ctx.fillStyle = '#ffffff'; 
                            ctx.fillText(d.text, 0, 0);
                        } else {
                            // A. Empty Text
                            ctx.fillStyle = 'rgba(255,255,255,0.3)'; 
                            ctx.fillText(d.text, 0, 0);

                            // B. Filled Text (Masked)
                            const fillW = boxW * progress;
                            const startX = -boxW/2;

                            ctx.save();
                            ctx.beginPath();
                            ctx.rect(startX, -boxH/2, fillW, boxH);
                            ctx.clip(); // Costly operation

                            ctx.shadowColor = d.color;
                            ctx.shadowBlur = 8;
                            ctx.fillStyle = '#ffffff';
                            ctx.fillText(d.text, 0, 0);

                            // Edge Glint
                            ctx.fillStyle = '#ffffff';
                            ctx.shadowBlur = 10;
                            ctx.fillRect(startX + fillW - 2, -boxH/2, 2, boxH);

                            ctx.restore();
                        }
                    }
                }

            } else {
                // DAMAGE / HEAL / CC (Simple Render)
                ctx.font = `900 ${d.size}px "Segoe UI", sans-serif`;
                ctx.lineWidth = 3;
                ctx.strokeStyle = 'rgba(0,0,0,0.8)';
                ctx.strokeText(d.text, 0, 0);
                ctx.fillStyle = d.color; 
                ctx.fillText(d.text, 0, 0);
            }

            ctx.restore();
            ctx.globalAlpha = 1.0;
        });
    }
};

const GRAVITY = 200;
const TEXT_LIFESPAN = 1.0;
// Reduced from 100 to 60 to prevent rendering bottlenecks during mass casting
const MAX_ACTIVE_TEXTS = 60; 

export interface FloatingText {
    active: boolean;
    x: number; 
    y: number;
    vx: number; 
    vy: number;
    text: string; 
    color: string;
    life: number; 
    maxLife: number;
    size: number;
    type: 'DAMAGE' | 'HEAL' | 'SHOUT' | 'CC' | 'KILL_STREAK';
    isUlt: boolean; 

    // New Props for Breakable Text
    ownerId?: string;      // 用於綁定單位
    isShattered?: boolean; // 標記是否已被打斷
    rotation: number;      // 物理旋轉角度
    vRot: number;          // 旋轉速度

    // Animation Timer
    time: number;          // 存活時間 (累加)
    totalDuration: number; // 預計總詠唱時間 (用於進度條計算)
}

export class HUDSystem {
    public damageNumbers: FloatingText[] = [];
    private pool: FloatingText[] = [];

    constructor() {
        for(let i=0; i<50; i++) this.pool.push(this.createEmpty());
    }

    public reset() {
        for (const d of this.damageNumbers) this.release(d);
        this.damageNumbers.length = 0;
    }

    private createEmpty(): FloatingText {
        return {
            active: false,
            x: 0, y: 0, vx: 0, vy: 0,
            text: '', color: '#fff', life: 0, maxLife: 0, size: 0,
            type: 'DAMAGE', isUlt: false,
            ownerId: undefined, isShattered: false, rotation: 0, vRot: 0,
            time: 0, totalDuration: 0
        };
    }

    public addFloatingText(
        x: number, y: number, text: string, color: string, size: number, 
        type: 'DAMAGE' | 'HEAL' | 'SHOUT' | 'CC' | 'KILL_STREAK' = 'DAMAGE', 
        isUlt: boolean = false,
        ownerId?: string,
        duration: number = 0 // 新增參數
    ) {
        if (this.damageNumbers.length > MAX_ACTIVE_TEXTS) {
            const old = this.damageNumbers.shift();
            if (old) this.release(old);
        }

        // Kill Streak 清理邏輯
        if (type === 'KILL_STREAK') {
            for (let i = this.damageNumbers.length - 1; i >= 0; i--) {
                if (this.damageNumbers[i].type === 'KILL_STREAK') {
                    this.release(this.damageNumbers[i]);
                    this.damageNumbers.splice(i, 1);
                }
            }
        }

        // 如果該單位已有存在的 SHOUT，先移除舊的 (避免重疊)
        if (type === 'SHOUT' && ownerId) {
            for (let i = this.damageNumbers.length - 1; i >= 0; i--) {
                const t = this.damageNumbers[i];
                if (t.type === 'SHOUT' && t.ownerId === ownerId && !t.isShattered) {
                    // 如果是舊的喊招，直接淡出或移除
                    t.life = 0; 
                }
            }
        }

        let vx = 0, vy = 0, life = TEXT_LIFESPAN;
        if (type === 'SHOUT') {
            // SHOUT 的生命週期現在由詠唱時間決定，但至少保留 1秒以免太快消失
            // Safety cap: Max 5s to prevent ghost text if duration is bugged
            const safeDuration = Math.min(5.0, duration > 0 ? duration : 1.0);
            life = safeDuration + 0.5;

            if (isUlt) { vy = -5; size = 24; }
            else { vy = -20; size = 14; }
        } else if (type === 'CC') {
            vy = -20; life = 1.5;
        } else if (type === 'KILL_STREAK') {
            vx = 0; vy = -30; life = 3.5; size = 32; 
        } else {
            vx = (Math.random() - 0.5) * 60; vy = -100; 
        }

        let ft = this.pool.length > 0 ? this.pool.pop()! : this.createEmpty();
        ft.active = true;
        ft.x = x; ft.y = y; ft.vx = vx; ft.vy = vy;
        ft.text = text; ft.color = color;
        ft.life = life; ft.maxLife = life;
        ft.size = size; ft.type = type;
        ft.isUlt = isUlt;
        ft.ownerId = ownerId;
        ft.isShattered = false;
        ft.rotation = 0;
        ft.vRot = 0;
        ft.time = 0;
        ft.totalDuration = duration > 0 ? duration : 1.0; 

        this.damageNumbers.push(ft);
    }

    /**
     * 核心功能：擊碎指定單位的詠唱文字
     */
    public breakCastText(ownerId: string) {
        // 尋找該單位目前正在活躍的 SHOUT
        const text = this.damageNumbers.find(t => t.type === 'SHOUT' && t.ownerId === ownerId && !t.isShattered);

        if (text) {
            text.isShattered = true;

            // 視覺崩壞物理效果
            text.color = '#94a3b8'; // 變成失效的灰色
            text.vy = -180; // 向上彈飛力度增加
            text.vx = (Math.random() - 0.5) * 250; // 增加水平飛散速度
            text.vRot = (Math.random() - 0.5) * 20; // 增加旋轉速度
            text.life = 0.5; // 壽命大幅縮短 (快速消失)
            text.maxLife = 0.5;
        }
    }

    private release(ft: FloatingText) {
        ft.active = false;
        ft.ownerId = undefined; // Clear Ref
        this.pool.push(ft);
    }

    public update(dt: number) {
        for (let i = this.damageNumbers.length - 1; i >= 0; i--) { 
            const d = this.damageNumbers[i]; 
            d.life -= dt; 
            d.time += dt;

            d.x += d.vx * dt;
            d.y += d.vy * dt; 
            d.rotation += d.vRot * dt; // Apply Rotation

            // Gravity Logic
            if (d.type === 'DAMAGE' || d.type === 'HEAL' || d.isShattered) {
                // Shattered text falls faster
                const g = d.isShattered ? GRAVITY * 3.0 : GRAVITY;
                d.vy += g * dt;
            }
            else if (d.type === 'SHOUT' || d.type === 'CC') d.vy *= 0.95; 
            else if (d.type === 'KILL_STREAK') d.vy *= 0.92; 

            if (d.life <= 0) {
                this.release(d);
                this.damageNumbers.splice(i, 1); 
            }
        }
    }
}

const GRAVITY = 200;
const TEXT_LIFESPAN = 1.0;
// Reduced from 100 to 60 to prevent rendering bottlenecks during mass casting
const MAX_ACTIVE_TEXTS = 60; 

export interface FloatingText {
    active: boolean;
    x: number; 
    y: number;
    vx: number; 
    vy: number;
    text: string; 
    color: string;
    life: number; 
    maxLife: number;
    size: number;
    type: 'DAMAGE' | 'HEAL' | 'SHOUT' | 'CC' | 'KILL_STREAK';
    isUlt: boolean; 

    // New Props for Breakable Text
    ownerId?: string;      // 用於綁定單位
    isShattered?: boolean; // 標記是否已被打斷
    rotation: number;      // 物理旋轉角度
    vRot: number;          // 旋轉速度

    // Animation Timer
    time: number;          // 存活時間 (累加)
    totalDuration: number; // 預計總詠唱時間 (用於進度條計算)
}

export class HUDSystem {
    public damageNumbers: FloatingText[] = [];
    private pool: FloatingText[] = [];

    constructor() {
        for(let i=0; i<50; i++) this.pool.push(this.createEmpty());
    }

    public reset() {
        for (const d of this.damageNumbers) this.release(d);
        this.damageNumbers.length = 0;
    }

    private createEmpty(): FloatingText {
        return {
            active: false,
            x: 0, y: 0, vx: 0, vy: 0,
            text: '', color: '#fff', life: 0, maxLife: 0, size: 0,
            type: 'DAMAGE', isUlt: false,
            ownerId: undefined, isShattered: false, rotation: 0, vRot: 0,
            time: 0, totalDuration: 0
        };
    }

    public addFloatingText(
        x: number, y: number, text: string, color: string, size: number, 
        type: 'DAMAGE' | 'HEAL' | 'SHOUT' | 'CC' | 'KILL_STREAK' = 'DAMAGE', 
        isUlt: boolean = false,
        ownerId?: string,
        duration: number = 0 // 新增參數
    ) {
        // 1. 強制數量上限檢查 (移除最舊的)
        if (this.damageNumbers.length >= MAX_ACTIVE_TEXTS) {
            const old = this.damageNumbers.shift();
            if (old) this.release(old);
        }

        // 2. Kill Streak 互斥清理
        if (type === 'KILL_STREAK') {
            for (let i = this.damageNumbers.length - 1; i >= 0; i--) {
                if (this.damageNumbers[i].type === 'KILL_STREAK') {
                    this.release(this.damageNumbers[i]);
                    this.damageNumbers.splice(i, 1);
                }
            }
        }

        // 3. 喊招互斥清理 (立即移除該單位舊的喊招)
        if (type === 'SHOUT' && ownerId) {
            for (let i = this.damageNumbers.length - 1; i >= 0; i--) {
                const t = this.damageNumbers[i];
                if (t.type === 'SHOUT' && t.ownerId === ownerId && !t.isShattered) {
                    this.release(t);
                    this.damageNumbers.splice(i, 1);
                }
            }
        }

        let vx = 0, vy = 0, life = TEXT_LIFESPAN;
        if (type === 'SHOUT') {
            // SHOUT 的生命週期現在由詠唱時間決定，但至少保留 1秒以免太快消失
            // Safety cap: Max 5s to prevent ghost text if duration is bugged
            const safeDuration = Math.min(5.0, duration > 0 ? duration : 1.0);
            life = safeDuration + 0.5;

            if (isUlt) { vy = -5; size = 24; }
            else { vy = -20; size = 14; }
        } else if (type === 'CC') {
            vy = -20; life = 1.5;
        } else if (type === 'KILL_STREAK') {
            vx = 0; vy = -30; life = 3.5; size = 32; 
        } else {
            vx = (Math.random() - 0.5) * 60; vy = -100; 
        }

        let ft = this.pool.length > 0 ? this.pool.pop()! : this.createEmpty();
        ft.active = true;
        ft.x = x; ft.y = y; ft.vx = vx; ft.vy = vy;
        ft.text = text; ft.color = color;
        ft.life = life; ft.maxLife = life;
        ft.size = size; ft.type = type;
        ft.isUlt = isUlt;
        ft.ownerId = ownerId;
        ft.isShattered = false;
        ft.rotation = 0;
        ft.vRot = 0;
        ft.time = 0;
        ft.totalDuration = duration > 0 ? duration : 1.0; 

        this.damageNumbers.push(ft);
    }

    /**
     * 核心功能：擊碎指定單位的詠唱文字
     */
    public breakCastText(ownerId: string) {
        // 尋找該單位目前正在活躍的 SHOUT
        const text = this.damageNumbers.find(t => t.type === 'SHOUT' && t.ownerId === ownerId && !t.isShattered);

        if (text) {
            text.isShattered = true;

            // 視覺崩壞物理效果
            text.color = '#94a3b8'; // 變成失效的灰色
            text.vy = -180; // 向上彈飛力度增加
            text.vx = (Math.random() - 0.5) * 250; // 增加水平飛散速度
            text.vRot = (Math.random() - 0.5) * 20; // 增加旋轉速度
            text.life = 0.5; // 壽命大幅縮短 (快速消失)
            text.maxLife = 0.5;
        }
    }

    private release(ft: FloatingText) {
        ft.active = false;
        ft.ownerId = undefined; // Clear Ref
        this.pool.push(ft);
    }

    public update(dt: number) {
        for (let i = this.damageNumbers.length - 1; i >= 0; i--) { 
            const d = this.damageNumbers[i]; 
            d.life -= dt; 
            d.time += dt;

            d.x += d.vx * dt;
            d.y += d.vy * dt; 
            d.rotation += d.vRot * dt; // Apply Rotation

            // Gravity Logic
            if (d.type === 'DAMAGE' || d.type === 'HEAL' || d.isShattered) {
                // Shattered text falls faster
                const g = d.isShattered ? GRAVITY * 3.0 : GRAVITY;
                d.vy += g * dt;
            }
            else if (d.type === 'SHOUT' || d.type === 'CC') d.vy *= 0.95; 
            else if (d.type === 'KILL_STREAK') d.vy *= 0.92; 

            if (d.life <= 0) {
                this.release(d);
                this.damageNumbers.splice(i, 1); 
            }
        }
    }
}

import { HUDSystem } from "../../systems/hud";

export const TextPainter = {

    drawFloatingText(ctx: CanvasRenderingContext2D, hud: HUDSystem) {
        const textCount = hud.damageNumbers.length;
        if (textCount === 0) return;

        // Optimization: Pre-set common drawing states
        ctx.textAlign = 'center';
        ctx.textBaseline = 'middle';
        ctx.shadowBlur = 0; // 確保關閉陰影

        hud.damageNumbers.forEach(d => {
            if (!d.active) return;

            const lifePct = d.life / d.maxLife;
            // Shattered text fades faster visually
            const alpha = d.isShattered ? lifePct : (lifePct < 0.3 ? lifePct / 0.3 : 1.0);

            // Optimization: Skip invisible text
            if (alpha <= 0.05) return;

            ctx.globalAlpha = alpha;

            // Save state for rotation transformation if needed
            ctx.save();
            ctx.translate(d.x, d.y);

            // Apply shatter rotation
            if (d.rotation !== 0) ctx.rotate(d.rotation);

            // Apply shatter scale (Explode outwards)
            if (d.isShattered) {
                const shatterProgress = 1 - lifePct;
                const scale = 1.0 + shatterProgress * 0.6; // Scale up to 1.6x
                ctx.scale(scale, scale);
                // Glitch offset for shattered text
                ctx.translate((Math.random()-0.5)*4, (Math.random()-0.5)*4);
            } else if (d.type === 'SHOUT') {
                // Active Shout Float Animation (Magical Levitation)
                const floatY = Math.sin(d.time * 6) * 3;
                ctx.translate(0, floatY);
            }

            if (d.type === 'KILL_STREAK') {
                // (Kill Streak logic remains same)
                const pop = Math.min(1, (1 - lifePct) * 5); 
                const pulse = 1 + Math.sin(lifePct * 10) * 0.1;
                const scale = pop * pulse * 1.5; 
                ctx.scale(scale, scale);
                ctx.font = `900 italic ${d.size}px "Arial Black", sans-serif`;

                const grad = ctx.createLinearGradient(0, -d.size/2, 0, d.size/2);
                grad.addColorStop(0, '#ffffff');
                grad.addColorStop(0.5, d.color);
                grad.addColorStop(1, '#000000');

                ctx.lineWidth = 4;
                ctx.lineJoin = 'round';
                ctx.strokeStyle = '#000';
                ctx.strokeText(d.text, 0, 0);
                ctx.fillStyle = grad;
                ctx.fillText(d.text, 0, 0);

            } else if (d.type === 'SHOUT') {
                // Optimization: Calculate metrics once
                ctx.font = d.isUlt ? `900 italic ${d.size}px "Arial Black", sans-serif` : `bold ${d.size}px "Segoe UI", sans-serif`;
                const textMetrics = ctx.measureText(d.text);
                const w = d.isUlt ? (textMetrics.width / 2 + 35) : textMetrics.width;
                const h = d.size + (d.isUlt ? 14 : 0);

                if (d.isUlt) {
                    // --- ULTIMATE CASTING VISUAL ---
                    const scale = 1 + (1 - lifePct) * 0.1; 
                    ctx.scale(scale, scale);

                    if (d.isShattered) {
                        // [OPTIMIZATION] Simple drawing for shattered state (No Clip, No Gradient, No Shadow)
                        // Simple dark rect
                        ctx.fillStyle = 'rgba(20, 0, 0, 0.5)';
                        ctx.fillRect(-w - 20, -h/2, w*2 + 40, h);

                        ctx.strokeStyle = '#ef4444';
                        ctx.lineWidth = 2;
                        ctx.beginPath(); ctx.moveTo(-w, -h/2); ctx.lineTo(0, -h/2); ctx.stroke();
                        ctx.beginPath(); ctx.moveTo(w, h/2); ctx.lineTo(0, h/2); ctx.stroke();

                        ctx.fillStyle = '#94a3b8';
                        ctx.fillText(d.text, 0, 0);
                    } else {
                        // ... Active Ult (Energy Filling) ...

                        // 1. Cinematic Bar Background (Simple Alpha Rect)
                        ctx.fillStyle = 'rgba(0,0,0,0.6)';
                        ctx.fillRect(-w - 40, -h/2 - 4, w*2 + 80, h + 8);

                        // 2. Glowing Borders (Stroke instead of Shadow)
                        const pulse = 0.5 + Math.sin(d.time * 10) * 0.5;
                        ctx.strokeStyle = d.color;
                        ctx.lineWidth = 2; 

                        ctx.beginPath();
                        ctx.moveTo(-w - 10, -h/2); ctx.lineTo(w + 10, -h/2);
                        ctx.moveTo(-w - 10, h/2); ctx.lineTo(w + 10, h/2);
                        ctx.stroke();

                        // 3. Brackets
                        ctx.fillStyle = d.color;
                        const bracketFont = `20px sans-serif`;
                        if (ctx.font !== bracketFont) ctx.font = bracketFont;
                        ctx.fillText("✦", -w - 20 - (pulse * 2), 1);
                        ctx.fillText("✦", w + 20 + (pulse * 2), 1);

                        // 4. TEXT FILLING LOGIC
                        ctx.font = `900 italic ${d.size}px "Arial Black", sans-serif`;

                        // Outline for contrast
                        ctx.lineWidth = 3;
                        ctx.strokeStyle = '#000';
                        ctx.strokeText(d.text, 0, 0);

                        // Calculate Progress
                        const progress = Math.min(1.0, d.time / d.totalDuration);

                        if (progress >= 1.0) {
                            // [OPTIMIZATION] Full Fill
                            ctx.fillStyle = '#ffffff';
                            ctx.fillText(d.text, 0, 0);
                        } else {
                            // A. Draw Empty Text (Dim)
                            ctx.fillStyle = 'rgba(255,255,255,0.3)';
                            ctx.fillText(d.text, 0, 0);

                            // B. Clipped Fill
                            const fillWidth = (w * 2 - 20) * progress; 
                            const startX = -w + 10;

                            ctx.save();
                            ctx.beginPath();
                            ctx.rect(startX, -h, fillWidth, h*2);
                            ctx.clip(); // Essential cost

                            // Simple fill instead of gradient for perf
                            ctx.fillStyle = d.color; // Or '#fff'
                            ctx.fillText(d.text, 0, 0);

                            // Energy Edge (Simple rect)
                            ctx.fillStyle = '#fff';
                            ctx.fillRect(startX + fillWidth - 1, -h/2, 2, h);

                            ctx.restore();
                        }
                    }

                } else {
                    // --- NORMAL CAST VISUAL ---
                    const padX = 14;
                    const padY = 8;
                    // w is full text width for normal cast
                    const boxW = w + padX * 2;
                    const boxH = d.size + padY * 2;

                    if (d.isShattered) {
                        // [OPTIMIZATION] Simple Render
                        ctx.fillStyle = 'rgba(30, 30, 30, 0.6)'; 
                        ctx.fillRect(-boxW/2, -boxH/2, boxW, boxH);

                        ctx.strokeStyle = 'rgba(255,50,50,0.3)';
                        ctx.lineWidth = 1;
                        ctx.strokeRect(-boxW/2, -boxH/2, boxW, boxH);

                        ctx.fillStyle = '#94a3b8'; 
                        ctx.fillText(d.text, 0, 0);
                    } else {
                        // Magic Box Background
                        ctx.fillStyle = 'rgba(15, 23, 42, 0.9)';

                        // Border
                        ctx.strokeStyle = d.color;
                        ctx.lineWidth = 1.5;

                        // Use simple rect instead of roundRect if possible for speed
                        ctx.beginPath();
                        ctx.rect(-boxW/2, -boxH/2, boxW, boxH);
                        ctx.fill();
                        ctx.stroke();

                        // FILLING TEXT LOGIC
                        const progress = Math.min(1.0, d.time / d.totalDuration);

                        if (progress >= 1.0) {
                            // [OPTIMIZATION] Full text
                            ctx.fillStyle = '#ffffff'; 
                            ctx.fillText(d.text, 0, 0);
                        } else {
                            // A. Empty Text
                            ctx.fillStyle = 'rgba(255,255,255,0.4)'; 
                            ctx.fillText(d.text, 0, 0);

                            // B. Filled Text (Masked)
                            const fillW = boxW * progress;
                            const startX = -boxW/2;

                            ctx.save();
                            ctx.beginPath();
                            ctx.rect(startX, -boxH/2, fillW, boxH);
                            ctx.clip(); // Costly operation

                            ctx.fillStyle = '#ffffff';
                            ctx.fillText(d.text, 0, 0);

                            // Edge Glint
                            ctx.fillStyle = '#ffffff';
                            ctx.fillRect(startX + fillW - 2, -boxH/2, 2, boxH);

                            ctx.restore();
                        }
                    }
                }

            } else {
                // DAMAGE / HEAL / CC (Simple Render)
                ctx.font = `900 ${d.size}px "Segoe UI", sans-serif`;
                ctx.lineWidth = 3;
                ctx.strokeStyle = 'rgba(0,0,0,0.8)';
                ctx.strokeText(d.text, 0, 0);
                ctx.fillStyle = d.color; 
                ctx.fillText(d.text, 0, 0);
            }

            ctx.restore();
            ctx.globalAlpha = 1.0;
        });
    }
};

const GRAVITY = 200;
const TEXT_LIFESPAN = 1.0;
// Reduced from 100 to 60 to prevent rendering bottlenecks during mass casting
const MAX_ACTIVE_TEXTS = 60; 

export interface FloatingText {
    active: boolean;
    x: number; 
    y: number;
    vx: number; 
    vy: number;
    text: string; 
    color: string;
    life: number; 
    maxLife: number;
    size: number;
    type: 'DAMAGE' | 'HEAL' | 'SHOUT' | 'CC' | 'KILL_STREAK';
    isUlt: boolean; 

    // New Props for Breakable Text
    ownerId?: string;      // 用於綁定單位
    isShattered?: boolean; // 標記是否已被打斷
    rotation: number;      // 物理旋轉角度
    vRot: number;          // 旋轉速度

    // Animation Timer
    time: number;          // 存活時間 (累加)
    totalDuration: number; // 預計總詠唱時間 (用於進度條計算)

    // Render Cache
    cachedWidth?: number; // 緩存文字寬度，避免每幀 measureText
}

export class HUDSystem {
    public damageNumbers: FloatingText[] = [];
    private pool: FloatingText[] = [];

    constructor() {
        for(let i=0; i<50; i++) this.pool.push(this.createEmpty());
    }

    public reset() {
        for (const d of this.damageNumbers) this.release(d);
        this.damageNumbers.length = 0;
    }

    private createEmpty(): FloatingText {
        return {
            active: false,
            x: 0, y: 0, vx: 0, vy: 0,
            text: '', color: '#fff', life: 0, maxLife: 0, size: 0,
            type: 'DAMAGE', isUlt: false,
            ownerId: undefined, isShattered: false, rotation: 0, vRot: 0,
            time: 0, totalDuration: 0, cachedWidth: undefined
        };
    }

    public addFloatingText(
        x: number, y: number, text: string, color: string, size: number, 
        type: 'DAMAGE' | 'HEAL' | 'SHOUT' | 'CC' | 'KILL_STREAK' = 'DAMAGE', 
        isUlt: boolean = false,
        ownerId?: string,
        duration: number = 0
    ) {
        // 1. 強制數量上限檢查 (移除最舊的)
        if (this.damageNumbers.length >= MAX_ACTIVE_TEXTS) {
            const old = this.damageNumbers.shift();
            if (old) this.release(old);
        }

        // 2. Kill Streak 互斥清理
        if (type === 'KILL_STREAK') {
            for (let i = this.damageNumbers.length - 1; i >= 0; i--) {
                if (this.damageNumbers[i].type === 'KILL_STREAK') {
                    this.release(this.damageNumbers[i]);
                    this.damageNumbers.splice(i, 1);
                }
            }
        }

        // 3. 喊招互斥清理 (立即移除該單位舊的喊招)
        if (type === 'SHOUT' && ownerId) {
            for (let i = this.damageNumbers.length - 1; i >= 0; i--) {
                const t = this.damageNumbers[i];
                if (t.type === 'SHOUT' && t.ownerId === ownerId && !t.isShattered) {
                    this.release(t);
                    this.damageNumbers.splice(i, 1);
                }
            }
        }

        let vx = 0, vy = 0, life = TEXT_LIFESPAN;
        if (type === 'SHOUT') {
            const safeDuration = Math.min(5.0, duration > 0 ? duration : 1.0);
            life = safeDuration + 0.5;

            if (isUlt) { vy = -5; size = 24; }
            else { vy = -20; size = 14; }
        } else if (type === 'CC') {
            vy = -20; life = 1.5;
        } else if (type === 'KILL_STREAK') {
            vx = 0; vy = -30; life = 3.5; size = 32; 
        } else {
            vx = (Math.random() - 0.5) * 60; vy = -100; 
        }

        let ft = this.pool.length > 0 ? this.pool.pop()! : this.createEmpty();
        ft.active = true;
        ft.x = x; ft.y = y; ft.vx = vx; ft.vy = vy;
        ft.text = text; ft.color = color;
        ft.life = life; ft.maxLife = life;
        ft.size = size; ft.type = type;
        ft.isUlt = isUlt;
        ft.ownerId = ownerId;
        ft.isShattered = false;
        ft.rotation = 0;
        ft.vRot = 0;
        ft.time = 0;
        ft.totalDuration = duration > 0 ? duration : 1.0; 
        ft.cachedWidth = undefined; // Reset width cache

        this.damageNumbers.push(ft);
    }

    public breakCastText(ownerId: string) {
        const text = this.damageNumbers.find(t => t.type === 'SHOUT' && t.ownerId === ownerId && !t.isShattered);

        if (text) {
            text.isShattered = true;
            text.color = '#94a3b8';
            text.vy = -180;
            text.vx = (Math.random() - 0.5) * 250;
            text.vRot = (Math.random() - 0.5) * 20;
            text.life = 0.5; 
            text.maxLife = 0.5;
        }
    }

    private release(ft: FloatingText) {
        ft.active = false;
        ft.ownerId = undefined;
        this.pool.push(ft);
    }

    public update(dt: number) {
        for (let i = this.damageNumbers.length - 1; i >= 0; i--) { 
            const d = this.damageNumbers[i]; 
            d.life -= dt; 
            d.time += dt;

            d.x += d.vx * dt;
            d.y += d.vy * dt; 
            d.rotation += d.vRot * dt; 

            if (d.type === 'DAMAGE' || d.type === 'HEAL' || d.isShattered) {
                const g = d.isShattered ? GRAVITY * 3.0 : GRAVITY;
                d.vy += g * dt;
            }
            else if (d.type === 'SHOUT' || d.type === 'CC') d.vy *= 0.95; 
            else if (d.type === 'KILL_STREAK') d.vy *= 0.92; 

            if (d.life <= 0) {
                this.release(d);
                this.damageNumbers.splice(i, 1); 
            }
        }
    }
}

