            // Early cull for nearly invisible text
            if (lifePct <= 0.05) return;

            const alpha = d.isShattered ? lifePct : (lifePct < 0.3 ? lifePct / 0.3 : 1.0);
            ctx.globalAlpha = alpha;

            ctx.save();
            ctx.translate(d.x, d.y);

            if (d.rotation !== 0) ctx.rotate(d.rotation);

            if (d.isShattered) {
                const shatterProgress = 1 - lifePct;
                const scale = 1.0 + shatterProgress * 0.6;
                ctx.scale(scale, scale);
                ctx.translate((Math.random()-0.5)*4, (Math.random()-0.5)*4);
            } else if (d.type === 'SHOUT') {
                const floatY = Math.sin(d.time * 6) * 3;
                ctx.translate(0, floatY);
            }

            if (d.type === 'KILL_STREAK') {
                // Kill Streak remains fancy (Gradient allowed, it's rare)
                const pop = Math.min(1, (1 - lifePct) * 5); 
                const pulse = 1 + Math.sin(lifePct * 10) * 0.1;
                const scale = pop * pulse * 1.5; 
                ctx.scale(scale, scale);
                ctx.font = `900 italic ${d.size}px "Arial Black", sans-serif`;

                // Simple stroke + fill instead of complex gradient
                ctx.lineWidth = 4;
                ctx.lineJoin = 'round';
                ctx.strokeStyle = '#000';
                ctx.strokeText(d.text, 0, 0);
                ctx.fillStyle = d.color;
                ctx.fillText(d.text, 0, 0);

            } else if (d.type === 'SHOUT') {
                // [OPTIMIZATION] Cache Width
                if (d.cachedWidth === undefined) {
                    ctx.font = d.isUlt ? `900 italic ${d.size}px "Arial Black", sans-serif` : `bold ${d.size}px "Segoe UI", sans-serif`;
                    d.cachedWidth = ctx.measureText(d.text).width;
                }

                const w = d.isUlt ? (d.cachedWidth! / 2 + 35) : d.cachedWidth!;
                const h = d.size + (d.isUlt ? 14 : 8);

                ctx.font = d.isUlt ? `900 italic ${d.size}px "Arial Black", sans-serif` : `bold ${d.size}px "Segoe UI", sans-serif`;

                if (d.isUlt) {
                    const scale = 1 + (1 - lifePct) * 0.1; 
                    ctx.scale(scale, scale);

                    if (d.isShattered) {
                        ctx.fillStyle = 'rgba(20, 0, 0, 0.5)';
                        ctx.fillRect(-w - 20, -h/2, w*2 + 40, h);

                        ctx.strokeStyle = '#ef4444';
                        ctx.lineWidth = 2;
                        ctx.beginPath(); ctx.moveTo(-w, -h/2); ctx.lineTo(0, -h/2); ctx.stroke();
                        ctx.beginPath(); ctx.moveTo(w, h/2); ctx.lineTo(0, h/2); ctx.stroke();

                        ctx.fillStyle = '#94a3b8';
                        ctx.fillText(d.text, 0, 0);
                    } else {
                        // Background
                        ctx.fillStyle = 'rgba(0,0,0,0.6)';
                        ctx.fillRect(-w - 40, -h/2 - 4, w*2 + 80, h + 8);

                        // Borders
                        ctx.strokeStyle = d.color;
                        ctx.lineWidth = 2; 
                        ctx.beginPath();
                        ctx.moveTo(-w - 10, -h/2); ctx.lineTo(w + 10, -h/2);
                        ctx.moveTo(-w - 10, h/2); ctx.lineTo(w + 10, h/2);
                        ctx.stroke();

                        // Brackets (Simple text, no font switch for perf if possible, or assume cheap)
                        // Actually, reusing same font is better. Using "||" or similar.
                        // Let's just draw lines for brackets to avoid font switch
                        ctx.fillStyle = d.color;
                        ctx.fillRect(-w - 25, -5, 4, 10); // Left dot
                        ctx.fillRect(w + 21, -5, 4, 10);  // Right dot

                        // Text Logic
                        ctx.lineWidth = 3;
                        ctx.strokeStyle = '#000';
                        ctx.strokeText(d.text, 0, 0);

                        const progress = Math.min(1.0, d.time / d.totalDuration);

                        // [OPTIMIZATION] Avoid CLIP. Draw dim text, then draw progress bar below.
                        // Draw full text (Dimmed if not done, Bright if done? No, let's keep fill effect but cheap)
                        // Cheap Fill: Draw Dim Text -> Draw Bright Rect over it with 'source-atop'? No.
                        // Cheapest: Draw Dim Text -> Draw Progress Bar at bottom.

                        if (progress >= 1.0) {
                            ctx.fillStyle = '#ffffff';
                            ctx.fillText(d.text, 0, 0);
                        } else {
                            // Dim Text
                            ctx.fillStyle = 'rgba(255,255,255,0.5)';
                            ctx.fillText(d.text, 0, 0);

                            // Progress Bar at bottom
                            const barW = (w * 2 + 60) * progress;
                            ctx.fillStyle = d.color;
                            ctx.fillRect(-w - 30, h/2 + 2, barW, 3);
                        }
                    }

                } else {
                    // Normal Shout
                    const boxW = w + 20;
                    const boxH = h;

                    if (d.isShattered) {
                        ctx.fillStyle = 'rgba(30, 30, 30, 0.6)'; 
                        ctx.fillRect(-boxW/2, -boxH/2, boxW, boxH);
                        ctx.strokeStyle = 'rgba(255,50,50,0.3)';
                        ctx.lineWidth = 1;
                        ctx.strokeRect(-boxW/2, -boxH/2, boxW, boxH);
                        ctx.fillStyle = '#94a3b8'; 
                        ctx.fillText(d.text, 0, 0);
                    } else {
                        ctx.fillStyle = 'rgba(15, 23, 42, 0.8)';
                        ctx.fillRect(-boxW/2, -boxH/2, boxW, boxH);

                        ctx.strokeStyle = d.color;
                        ctx.lineWidth = 1;
                        ctx.strokeRect(-boxW/2, -boxH/2, boxW, boxH);

                        const progress = Math.min(1.0, d.time / d.totalDuration);

                        if (progress >= 1.0) {
                            ctx.fillStyle = '#ffffff'; 
                            ctx.fillText(d.text, 0, 0);
                        } else {
                            // Dim Text
                            ctx.fillStyle = 'rgba(255,255,255,0.6)'; 
                            ctx.fillText(d.text, 0, 0);

                            // Progress Bar (Simple Underline)
                            const fillW = boxW * progress;
                            ctx.fillStyle = '#fff';
                            ctx.fillRect(-boxW/2, boxH/2 - 2, fillW, 2);
                        }
                    }
                }

            } else {
                // DAMAGE / HEAL / CC
                // Optimization: Skip font setting if similar? No, simple is fine.
                ctx.font = `900 ${d.size}px "Segoe UI", sans-serif`;
                ctx.lineWidth = 3;
                ctx.strokeStyle = 'rgba(0,0,0,0.8)';
                ctx.strokeText(d.text, 0, 0);
                ctx.fillStyle = d.color; 
                ctx.fillText(d.text, 0, 0);
            }

            ctx.restore();
            ctx.globalAlpha = 1.0;
        });
    }
};

import { Agent, GameEngine } from "../game";
import { NodeState } from "../../types";
import { HexUtils } from "../utils";

export type BTConditionFn = (agent: Agent, engine: GameEngine, args?: any) => boolean;
export type BTActionFn = (agent: Agent, engine: GameEngine, args?: any) => NodeState;

export const BTConditions: Record<string, BTConditionFn> = {
    "IsDead": (a) => a.hp <= 0,
    "IsAlive": (a) => a.hp > 0,
    "IsStunned": (a) => a.stunTimer > 0,
    "IsBanished": (a) => a.banishTimer > 0,
    "IsSilenced": (a) => a.silenceTimer > 0,
    "IsFeared": (a) => a.fearTimer > 0, 
    "HasTarget": (a, engine) => {
        // RTS 頻率：每 0.5 秒強制掃描一次威脅最高目標，或在沒有目標時掃描
        if (engine.battleTime % 0.5 < 0.02 || !a.target) {
            engine.updateTarget(a);
        }
        return a.target !== null;
    },
    "HpBelow": (a, _, args) => (a.hp / a.maxHp) < args.threshold,
    "MpAbove": (a, _, args) => a.mp >= args.amount,
    "SkillReady": (a, _, args) => {
        const idx = args.slot; 
        const s = a.skills[idx];
        if (!s) return false;
        // 數學容差 CD 檢查
        return a.curCDs[idx] <= 0.01 && a.mp >= s.cost && a.stunTimer <= 0 && !a.banished;
    },
    "FindOptimalTarget": (a, engine, args) => {
        const idx = args.slot;
        const skill = a.skills[idx];
        if (!skill) return false;

        // 執行數學權重搜索
        const res = engine.calculateOptimalTarget(a, skill);
        if (res.targetAgent) {
            a.target = res.targetAgent;
            a.targetHex = null;
        } else if (res.targetHex) {
            a.target = null;
            a.targetHex = res.targetHex;
        }
        return (a.target !== null || a.targetHex !== null);
    },
    "IsTargetInRange": (a, engine, args) => {
        const idx = args.slot;
        const skill = a.skills[idx];
        if (!skill) return false;
        const targetPos = a.targetHex || (a.target ? {q: a.target.q, r: a.target.r} : null);
        if (!targetPos) return false;

        // 使用動態射程判定 (考慮地勢)
        const effRange = engine.getEffectiveRange(a, targetPos.q, targetPos.r, skill.range);
        return HexUtils.dist(a, targetPos) <= effRange;
    }
};

export const BTActions: Record<string, BTActionFn> = {
    "Wait": (a, engine, args) => {
        a.btStatus = args.status || "等待";
        return NodeState.RUNNING;
    },
    "Idle": (a) => {
        a.btStatus = "待機中";
        return NodeState.SUCCESS;
    },
    "CastSkill": (a, engine, args) => {
        const idx = args.slot;
        return engine.initiateCast(a, idx);
    },
    "MoveToOptimal": (a, engine, args) => {
        const idx = args.slot;
        const skill = a.skills[idx];
        const targetPos = a.targetHex || (a.target ? {q: a.target.q, r: a.target.r} : null);
        if (!skill || !targetPos) return NodeState.FAILURE;

        const speedMult = (skill.tag === 'ULT') ? 1.3 : 1.0;
        return engine.moveAgentToHex(a, targetPos, skill.range, speedMult);
    },
    "ChaseTarget": (a, engine, args) => {
        const idx = args.slot;
        const skill = a.skills[idx];
        if (!skill || !a.target) return NodeState.FAILURE;

        // RTS 優化：攔截預判
        // 只有當目標距離我「預定路徑終點」超過容差時才重新計算 A*
        const currentGoal = a.path.length > 0 ? a.path[a.path.length - 1] : null;
        const tolerance = (a.target.isMoving) ? 1.5 : 0.5;
        const needsNewPath = !currentGoal || HexUtils.dist(currentGoal, a.target) > tolerance;

        if (needsNewPath) {
            const speedMult = (skill.tag === 'ULT') ? 1.4 : 1.1;
            a.btStatus = `截擊 ${a.target.id}`;
            return engine.moveAgentToHex(a, {q: a.target.q, r: a.target.r}, skill.range, speedMult);
        }

        return NodeState.RUNNING;
    }
};

// Fix: Use 'import type' to break circular dependency with GameEngine
import type { Agent, GameEngine } from "../game";
import { NodeState } from "../../types";
import { HexUtils } from "../utils";
import { HEX_SIZE } from "../../constants";

export type BTConditionFn = (agent: Agent, engine: GameEngine, args?: any) => boolean;
export type BTActionFn = (agent: Agent, engine: GameEngine, args?: any) => NodeState;

export const BTConditions: Record<string, BTConditionFn> = {
    "IsDead": (a) => a.hp <= 0,
    "IsAlive": (a) => a.hp > 0,
    "IsStunned": (a) => a.stunTimer > 0,
    "IsBanished": (a) => a.banishTimer > 0,
    "IsSilenced": (a) => a.silenceTimer > 0,
    "IsFeared": (a) => a.fearTimer > 0, 

    "HasTarget": (a, engine) => {
        if (a.target && a.target.hp > 0 && !a.target.banished) {
            return true; 
        }
        if (a.aiUpdateTimer <= 0 || !a.target || a.target.hp <= 0) {
            engine.updateTarget(a);
            a.aiUpdateTimer = a.aiUpdateInterval; 
        }
        return a.target !== null;
    },

    "HpBelow": (a, _, args) => (a.hp / a.maxHp) < args.threshold,
    "MpAbove": (a, _, args) => a.mp >= args.amount,

    "SkillReady": (a, _, args) => {
        const idx = args.slot; 
        const s = a.skills[idx];
        if (!s) return false;

        let cd = a.curCDs[idx];
        if (isNaN(cd)) cd = 0;

        const tolerance = (s.tag === 'BASIC') ? 0.15 : 0.01;
        const isOnCD = cd > tolerance; 

        if (isOnCD || a.mp < s.cost) return false;
        if (a.stunTimer > 0 || a.banished || a.fearTimer > 0) return false;
        if (a.silenceTimer > 0 && s.tag !== 'BASIC') return false;

        return true;
    },

    "FindOptimalTarget": (a, engine, args) => {
        const idx = args.slot;
        const skill = a.skills[idx];
        if (!skill) return false;

        const result = engine.calculateOptimalTarget(a, skill);

        if (result.targetAgent) {
            a.target = result.targetAgent;
            a.targetHex = null;
            return true;
        } else if (result.targetHex) {
            a.target = null;
            a.targetHex = result.targetHex;
            return true;
        }
        return false;
    },

    "IsTargetInRange": (a, engine, args) => {
        const idx = args.slot;
        const skill = a.skills[idx];
        if (!skill) return false;

        let tQ = 0, tR = 0;
        if (a.targetHex) { tQ = a.targetHex.q; tR = a.targetHex.r; }
        else if (a.target) { tQ = a.target.q; tR = a.target.r; }
        else return false;

        const effRange = engine.getEffectiveRange(a, tQ, tR, skill.range);
        const gridDist = a.targetHex ? HexUtils.dist(a, a.targetHex) : HexUtils.dist(a, a.target!);

        if (gridDist > effRange + 0.5) return false;

        if (effRange <= 1.0) {
            const startPx = HexUtils.toPx(a.q, a.r, engine.mapConfig);
            let endPx;
            if (a.targetHex) endPx = HexUtils.toPx(a.targetHex.q, a.targetHex.r, engine.mapConfig);
            else endPx = { x: a.target!.px, y: a.target!.py };
            const dx = startPx.x - endPx.x;
            const dy = startPx.y - endPx.y;
            const pxDist = Math.sqrt(dx*dx + dy*dy);

            if (pxDist > HEX_SIZE * 2.8) return false;
        }

        return true;
    }
};

export const BTActions: Record<string, BTActionFn> = {
    "Wait": (a, engine, args) => {
        a.btStatus = args.status || "等待";
        return NodeState.RUNNING;
    },
    "Idle": (a) => {
        a.btStatus = "待機中";
        if (a.isMoving) {
            a.isMoving = false;
            a.path = [];
        }
        return NodeState.SUCCESS;
    },
    "CastSkill": (a, engine, args) => {
        const idx = args.slot;
        return engine.initiateCast(a, idx);
    },
    "MoveToOptimal": (a, engine, args) => {
        const idx = args.slot;
        const skill = a.skills[idx];
        if (!skill) return NodeState.FAILURE;
        const speedMult = (skill.tag === 'ULT') ? 1.3 : 1.0;
        let dest = a.targetHex || (a.target ? {q: a.target.q, r: a.target.r} : null);

        if (dest) {
            if (a.q === dest.q && a.r === dest.r) return NodeState.SUCCESS;
            return engine.moveAgentToHex(a, dest, skill.range, speedMult);
        }
        return NodeState.FAILURE;
    },
    "ChaseTarget": (a, engine, args) => {
        const idx = args.slot;
        const skill = a.skills[idx];
        if (!skill || !a.target) return NodeState.FAILURE;
        const speedMult = (skill.tag === 'ULT') ? 1.4 : 1.1;
        a.btStatus = `追蹤 ${a.target.id}`;
        return engine.moveAgentToHex(a, {q: a.target.q, r: a.target.r}, skill.range, speedMult);
    }
};

import { HUDSystem } from "../../systems/hud";

export const TextPainter = {

    drawFloatingText(ctx: CanvasRenderingContext2D, hud: HUDSystem) {
        const textCount = hud.damageNumbers.length;
        if (textCount === 0) return;

        ctx.textAlign = 'center';
        ctx.textBaseline = 'middle';
        ctx.shadowBlur = 0; 

        hud.damageNumbers.forEach(d => {
            if (!d.active) return;

            const lifePct = d.life / d.maxLife;
            // Early cull for nearly invisible text
            if (lifePct <= 0.05) return;

            const alpha = d.isShattered ? lifePct : (lifePct < 0.3 ? lifePct / 0.3 : 1.0);
            ctx.globalAlpha = alpha;

            ctx.save();
            ctx.translate(d.x, d.y);

            if (d.rotation !== 0) ctx.rotate(d.rotation);

            if (d.isShattered) {
                const shatterProgress = 1 - lifePct;
                const scale = 1.0 + shatterProgress * 0.6;
                ctx.scale(scale, scale);
                ctx.translate((Math.random()-0.5)*4, (Math.random()-0.5)*4);
            } else if (d.type === 'SHOUT') {
                const floatY = Math.sin(d.time * 6) * 3;
                ctx.translate(0, floatY);
            }

            if (d.type === 'KILL_STREAK') {
                const pop = Math.min(1, (1 - lifePct) * 5); 
                const pulse = 1 + Math.sin(lifePct * 10) * 0.1;
                const scale = pop * pulse * 1.5; 
                ctx.scale(scale, scale);
                ctx.font = `900 italic ${d.size}px "Arial Black", sans-serif`;

                ctx.lineWidth = 4;
                ctx.lineJoin = 'round';
                ctx.strokeStyle = '#000';
                ctx.strokeText(d.text, 0, 0);
                ctx.fillStyle = d.color;
                ctx.fillText(d.text, 0, 0);

            } else if (d.type === 'SHOUT') {
                // [OPTIMIZATION] Cache Width
                if (d.cachedWidth === undefined) {
                    ctx.font = d.isUlt ? `900 italic ${d.size}px "Arial Black", sans-serif` : `bold ${d.size}px "Segoe UI", sans-serif`;
                    d.cachedWidth = ctx.measureText(d.text).width;
                }

                const w = d.isUlt ? (d.cachedWidth! / 2 + 35) : d.cachedWidth!;
                const h = d.size + (d.isUlt ? 14 : 8);

                ctx.font = d.isUlt ? `900 italic ${d.size}px "Arial Black", sans-serif` : `bold ${d.size}px "Segoe UI", sans-serif`;

                if (d.isUlt) {
                    const scale = 1 + (1 - lifePct) * 0.1; 
                    ctx.scale(scale, scale);

                    if (d.isShattered) {
                        ctx.fillStyle = 'rgba(20, 0, 0, 0.5)';
                        ctx.fillRect(-w - 20, -h/2, w*2 + 40, h);

                        ctx.strokeStyle = '#ef4444';
                        ctx.lineWidth = 2;
                        ctx.beginPath(); ctx.moveTo(-w, -h/2); ctx.lineTo(0, -h/2); ctx.stroke();
                        ctx.beginPath(); ctx.moveTo(w, h/2); ctx.lineTo(0, h/2); ctx.stroke();

                        ctx.fillStyle = '#94a3b8';
                        ctx.fillText(d.text, 0, 0);
                    } else {
                        // Background
                        ctx.fillStyle = 'rgba(0,0,0,0.6)';
                        ctx.fillRect(-w - 40, -h/2 - 4, w*2 + 80, h + 8);

                        // Borders
                        ctx.strokeStyle = d.color;
                        ctx.lineWidth = 2; 
                        ctx.beginPath();
                        ctx.moveTo(-w - 10, -h/2); ctx.lineTo(w + 10, -h/2);
                        ctx.moveTo(-w - 10, h/2); ctx.lineTo(w + 10, h/2);
                        ctx.stroke();

                        ctx.fillStyle = d.color;
                        ctx.fillRect(-w - 25, -5, 4, 10); // Left dot
                        ctx.fillRect(w + 21, -5, 4, 10);  // Right dot

                        // Text
                        ctx.lineWidth = 3;
                        ctx.strokeStyle = '#000';
                        ctx.strokeText(d.text, 0, 0);

                        const progress = Math.min(1.0, d.time / d.totalDuration);

                        if (progress >= 1.0) {
                            ctx.fillStyle = '#ffffff';
                            ctx.fillText(d.text, 0, 0);
                        } else {
                            // Dim Text
                            ctx.fillStyle = 'rgba(255,255,255,0.5)';
                            ctx.fillText(d.text, 0, 0);

                            // Progress Bar at bottom
                            const barW = (w * 2 + 60) * progress;
                            ctx.fillStyle = d.color;
                            ctx.fillRect(-w - 30, h/2 + 2, barW, 3);
                        }
                    }

                } else {
                    // Normal Shout
                    const boxW = w + 20;
                    const boxH = h;

                    if (d.isShattered) {
                        ctx.fillStyle = 'rgba(30, 30, 30, 0.6)'; 
                        ctx.fillRect(-boxW/2, -boxH/2, boxW, boxH);
                        ctx.strokeStyle = 'rgba(255,50,50,0.3)';
                        ctx.lineWidth = 1;
                        ctx.strokeRect(-boxW/2, -boxH/2, boxW, boxH);
                        ctx.fillStyle = '#94a3b8'; 
                        ctx.fillText(d.text, 0, 0);
                    } else {
                        ctx.fillStyle = 'rgba(15, 23, 42, 0.8)';
                        ctx.fillRect(-boxW/2, -boxH/2, boxW, boxH);

                        ctx.strokeStyle = d.color;
                        ctx.lineWidth = 1;
                        ctx.strokeRect(-boxW/2, -boxH/2, boxW, boxH);

                        const progress = Math.min(1.0, d.time / d.totalDuration);

                        if (progress >= 1.0) {
                            ctx.fillStyle = '#ffffff'; 
                            ctx.fillText(d.text, 0, 0);
                        } else {
                            ctx.fillStyle = 'rgba(255,255,255,0.6)'; 
                            ctx.fillText(d.text, 0, 0);
                            const fillW = boxW * progress;
                            ctx.fillStyle = '#fff';
                            ctx.fillRect(-boxW/2, boxH/2 - 2, fillW, 2);
                        }
                    }
                }

            } else {
                ctx.font = `900 ${d.size}px "Segoe UI", sans-serif`;
                ctx.lineWidth = 3;
                ctx.strokeStyle = 'rgba(0,0,0,0.8)';
                ctx.strokeText(d.text, 0, 0);
                ctx.fillStyle = d.color; 
                ctx.fillText(d.text, 0, 0);
            }

            ctx.restore();
            ctx.globalAlpha = 1.0;
        });
    }
};

const GRAVITY = 200;
const TEXT_LIFESPAN = 1.0;
const MAX_ACTIVE_TEXTS = 100;

export interface FloatingText {
    active: boolean;
    x: number; 
    y: number;
    vx: number; 
    vy: number;
    text: string; 
    color: string;
    life: number; 
    maxLife: number;
    size: number;
    type: 'DAMAGE' | 'HEAL' | 'SHOUT' | 'CC' | 'KILL_STREAK';
    isUlt: boolean; 

    // New Props for Breakable Text
    ownerId?: string;      // 用於綁定單位
    isShattered?: boolean; // 標記是否已被打斷
    rotation: number;      // 物理旋轉角度
    vRot: number;          // 旋轉速度

    // Animation Timer
    time: number;          // 存活時間 (累加)
    totalDuration: number; // 預計總詠唱時間 (用於進度條計算)
    cachedWidth?: number;  // Cached width for text measurement optimization
}

export class HUDSystem {
    public damageNumbers: FloatingText[] = [];
    private pool: FloatingText[] = [];

    constructor() {
        for(let i=0; i<50; i++) this.pool.push(this.createEmpty());
    }

    public reset() {
        for (const d of this.damageNumbers) this.release(d);
        this.damageNumbers.length = 0;
    }

    private createEmpty(): FloatingText {
        return {
            active: false,
            x: 0, y: 0, vx: 0, vy: 0,
            text: '', color: '#fff', life: 0, maxLife: 0, size: 0,
            type: 'DAMAGE', isUlt: false,
            ownerId: undefined, isShattered: false, rotation: 0, vRot: 0,
            time: 0, totalDuration: 0, cachedWidth: undefined
        };
    }

    public addFloatingText(
        x: number, y: number, text: string, color: string, size: number, 
        type: 'DAMAGE' | 'HEAL' | 'SHOUT' | 'CC' | 'KILL_STREAK' = 'DAMAGE', 
        isUlt: boolean = false,
        ownerId?: string,
        duration: number = 0 // 新增參數
    ) {
        if (this.damageNumbers.length > MAX_ACTIVE_TEXTS) {
            const old = this.damageNumbers.shift();
            if (old) this.release(old);
        }

        // Kill Streak 清理邏輯
        if (type === 'KILL_STREAK') {
            for (let i = this.damageNumbers.length - 1; i >= 0; i--) {
                if (this.damageNumbers[i].type === 'KILL_STREAK') {
                    this.release(this.damageNumbers[i]);
                    this.damageNumbers.splice(i, 1);
                }
            }
        }

        // 如果該單位已有存在的 SHOUT，先移除舊的 (避免重疊)
        if (type === 'SHOUT' && ownerId) {
            for (let i = this.damageNumbers.length - 1; i >= 0; i--) {
                const t = this.damageNumbers[i];
                if (t.type === 'SHOUT' && t.ownerId === ownerId && !t.isShattered) {
                    // 如果是舊的喊招，直接淡出或移除
                    t.life = 0; 
                }
            }
        }

        let vx = 0, vy = 0, life = TEXT_LIFESPAN;
        if (type === 'SHOUT') {
            // SHOUT 的生命週期現在由詠唱時間決定，但至少保留 1秒以免太快消失
            // 我們給予一點緩衝時間讓它在詠唱完後還能稍微顯示一下 (fadeOut)
            life = Math.max(duration, 1.0) + 0.3;
            if (isUlt) { vy = -5; size = 24; }
            else { vy = -20; size = 14; }
        } else if (type === 'CC') {
            vy = -20; life = 1.5;
        } else if (type === 'KILL_STREAK') {
            vx = 0; vy = -30; life = 3.5; size = 32; 
        } else {
            vx = (Math.random() - 0.5) * 60; vy = -100; 
        }

        let ft = this.pool.length > 0 ? this.pool.pop()! : this.createEmpty();
        ft.active = true;
        ft.x = x; ft.y = y; ft.vx = vx; ft.vy = vy;
        ft.text = text; ft.color = color;
        ft.life = life; ft.maxLife = life;
        ft.size = size; ft.type = type;
        ft.isUlt = isUlt;
        ft.ownerId = ownerId;
        ft.isShattered = false;
        ft.rotation = 0;
        ft.vRot = 0;
        ft.time = 0;
        ft.totalDuration = duration > 0 ? duration : 1.0; // 防止除以零
        ft.cachedWidth = undefined; // Reset cached width

        this.damageNumbers.push(ft);
    }

    /**
     * 核心功能：擊碎指定單位的詠唱文字
     */
    public breakCastText(ownerId: string) {
        // 尋找該單位目前正在活躍的 SHOUT
        const text = this.damageNumbers.find(t => t.type === 'SHOUT' && t.ownerId === ownerId && !t.isShattered);

        if (text) {
            text.isShattered = true;

            // 視覺崩壞物理效果
            text.color = '#94a3b8'; // 變成失效的灰色
            text.vy = -180; // 向上彈飛力度增加
            text.vx = (Math.random() - 0.5) * 250; // 增加水平飛散速度
            text.vRot = (Math.random() - 0.5) * 20; // 增加旋轉速度
            text.life = 0.5; // 壽命大幅縮短 (快速消失)
            text.maxLife = 0.5;
        }
    }

    private release(ft: FloatingText) {
        ft.active = false;
        ft.ownerId = undefined; // Clear Ref
        this.pool.push(ft);
    }

    public update(dt: number) {
        for (let i = this.damageNumbers.length - 1; i >= 0; i--) { 
            const d = this.damageNumbers[i]; 
            d.life -= dt; 
            d.time += dt;

            d.x += d.vx * dt;
            d.y += d.vy * dt; 
            d.rotation += d.vRot * dt; // Apply Rotation

            // Gravity Logic
            if (d.type === 'DAMAGE' || d.type === 'HEAL' || d.isShattered) {
                // Shattered text falls faster
                const g = d.isShattered ? GRAVITY * 3.0 : GRAVITY;
                d.vy += g * dt;
            }
            else if (d.type === 'SHOUT' || d.type === 'CC') d.vy *= 0.95; 
            else if (d.type === 'KILL_STREAK') d.vy *= 0.92; 

            if (d.life <= 0) {
                this.release(d);
                this.damageNumbers.splice(i, 1); 
            }
        }
    }
}

// Fix: Use 'import type' to break circular dependency with GameEngine
import type { Agent, GameEngine } from "../game";
import { NodeState } from "../../types";
import { HexUtils } from "../utils";
import { HEX_SIZE } from "../../constants";

export type BTConditionFn = (agent: Agent, engine: GameEngine, args?: any) => boolean;
export type BTActionFn = (agent: Agent, engine: GameEngine, args?: any) => NodeState;

export const BTConditions: Record<string, BTConditionFn> = {
    "IsDead": (a) => a.hp <= 0,
    "IsAlive": (a) => a.hp > 0,
    "IsStunned": (a) => a.stunTimer > 0,
    "IsBanished": (a) => a.banishTimer > 0,
    "IsSilenced": (a) => a.silenceTimer > 0,
    "IsFeared": (a) => a.fearTimer > 0, 

    "HasTarget": (a, engine) => {
        if (a.target && a.target.hp > 0 && !a.target.banished) {
            return true; 
        }
        if (a.aiUpdateTimer <= 0 || !a.target || a.target.hp <= 0) {
            engine.updateTarget(a);
            a.aiUpdateTimer = a.aiUpdateInterval; 
        }
        return a.target !== null;
    },

    "HpBelow": (a, _, args) => (a.hp / a.maxHp) < args.threshold,
    "MpAbove": (a, _, args) => a.mp >= args.amount,

    "SkillReady": (a, _, args) => {
        const idx = args.slot; 
        const s = a.skills[idx];
        if (!s) return false;

        let cd = a.curCDs[idx];
        if (isNaN(cd)) cd = 0;

        const tolerance = (s.tag === 'BASIC') ? 0.15 : 0.01;
        const isOnCD = cd > tolerance; 

        if (isOnCD || a.mp < s.cost) return false;
        if (a.stunTimer > 0 || a.banished || a.fearTimer > 0) return false;
        if (a.silenceTimer > 0 && s.tag !== 'BASIC') return false;

        return true;
    },

    "FindOptimalTarget": (a, engine, args) => {
        const idx = args.slot;
        const skill = a.skills[idx];
        if (!skill) return false;

        const result = engine.calculateOptimalTarget(a, skill);

        if (result.targetAgent) {
            a.target = result.targetAgent;
            a.targetHex = null;
            return true;
        } else if (result.targetHex) {
            a.target = null;
            a.targetHex = result.targetHex;
            return true;
        }
        return false;
    },

    "IsTargetInRange": (a, engine, args) => {
        const idx = args.slot;
        const skill = a.skills[idx];
        if (!skill) return false;

        let tQ = 0, tR = 0;
        if (a.targetHex) { tQ = a.targetHex.q; tR = a.targetHex.r; }
        else if (a.target) { tQ = a.target.q; tR = a.target.r; }
        else return false;

        const effRange = engine.getEffectiveRange(a, tQ, tR, skill.range);
        const gridDist = a.targetHex ? HexUtils.dist(a, a.targetHex) : HexUtils.dist(a, a.target!);

        if (gridDist > effRange + 0.5) return false;

        if (effRange <= 1.0) {
            const startPx = HexUtils.toPx(a.q, a.r, engine.mapConfig);
            let endPx;
            if (a.targetHex) endPx = HexUtils.toPx(a.targetHex.q, a.targetHex.r, engine.mapConfig);
            else endPx = { x: a.target!.px, y: a.target!.py };
            const dx = startPx.x - endPx.x;
            const dy = startPx.y - endPx.y;
            const pxDist = Math.sqrt(dx*dx + dy*dy);

            if (pxDist > HEX_SIZE * 2.8) return false;
        }

        return true;
    }
};

export const BTActions: Record<string, BTActionFn> = {
    "Wait": (a, engine, args) => {
        a.btStatus = args.status || "等待";
        return NodeState.RUNNING;
    },
    "Idle": (a) => {
        a.btStatus = "待機中";
        if (a.isMoving) {
            a.isMoving = false;
            a.path = [];
        }
        return NodeState.SUCCESS;
    },
    "CastSkill": (a, engine, args) => {
        const idx = args.slot;
        return engine.initiateCast(a, idx);
    },
    "MoveToOptimal": (a, engine, args) => {
        const idx = args.slot;
        const skill = a.skills[idx];
        if (!skill) return NodeState.FAILURE;
        const speedMult = (skill.tag === 'ULT') ? 1.3 : 1.0;
        let dest = a.targetHex || (a.target ? {q: a.target.q, r: a.target.r} : null);

        if (dest) {
            if (a.q === dest.q && a.r === dest.r) return NodeState.SUCCESS;
            return engine.moveAgentToHex(a, dest, skill.range, speedMult);
        }
        return NodeState.FAILURE;
    },
    "ChaseTarget": (a, engine, args) => {
        const idx = args.slot;
        const skill = a.skills[idx];
        if (!skill || !a.target) return NodeState.FAILURE;
        const speedMult = (skill.tag === 'ULT') ? 1.4 : 1.1;
        a.btStatus = `追蹤 ${a.target.id}`;
        return engine.moveAgentToHex(a, {q: a.target.q, r: a.target.r}, skill.range, speedMult);
    }
};

const GRAVITY = 200;
const TEXT_LIFESPAN = 1.0;
const MAX_ACTIVE_TEXTS = 60; // Reduced for performance safety

export interface FloatingText {
    active: boolean;
    x: number; 
    y: number;
    vx: number; 
    vy: number;
    text: string; 
    color: string;
    life: number; 
    maxLife: number;
    size: number;
    type: 'DAMAGE' | 'HEAL' | 'SHOUT' | 'CC' | 'KILL_STREAK';
    isUlt: boolean; 

    // New Props for Breakable Text
    ownerId?: string;      // 用於綁定單位
    isShattered?: boolean; // 標記是否已被打斷
    rotation: number;      // 物理旋轉角度
    vRot: number;          // 旋轉速度

    // Animation Timer
    time: number;          // 存活時間 (累加)
    totalDuration: number; // 預計總詠唱時間 (用於進度條計算)
    cachedWidth?: number;  // Cached width for text measurement optimization
}

export class HUDSystem {
    public damageNumbers: FloatingText[] = [];
    private pool: FloatingText[] = [];

    constructor() {
        for(let i=0; i<50; i++) this.pool.push(this.createEmpty());
    }

    public reset() {
        for (const d of this.damageNumbers) this.release(d);
        this.damageNumbers.length = 0;
    }

    private createEmpty(): FloatingText {
        return {
            active: false,
            x: 0, y: 0, vx: 0, vy: 0,
            text: '', color: '#fff', life: 0, maxLife: 0, size: 0,
            type: 'DAMAGE', isUlt: false,
            ownerId: undefined, isShattered: false, rotation: 0, vRot: 0,
            time: 0, totalDuration: 0, cachedWidth: undefined
        };
    }

    public addFloatingText(
        x: number, y: number, text: string, color: string, size: number, 
        type: 'DAMAGE' | 'HEAL' | 'SHOUT' | 'CC' | 'KILL_STREAK' = 'DAMAGE', 
        isUlt: boolean = false,
        ownerId?: string,
        duration: number = 0
    ) {
        if (this.damageNumbers.length >= MAX_ACTIVE_TEXTS) {
            const old = this.damageNumbers.shift();
            if (old) this.release(old);
        }

        // Kill Streak 清理邏輯
        if (type === 'KILL_STREAK') {
            for (let i = this.damageNumbers.length - 1; i >= 0; i--) {
                if (this.damageNumbers[i].type === 'KILL_STREAK') {
                    this.release(this.damageNumbers[i]);
                    this.damageNumbers.splice(i, 1);
                }
            }
        }

        // 如果該單位已有存在的 SHOUT，先移除舊的 (避免重疊)
        if (type === 'SHOUT' && ownerId) {
            for (let i = this.damageNumbers.length - 1; i >= 0; i--) {
                const t = this.damageNumbers[i];
                if (t.type === 'SHOUT' && t.ownerId === ownerId && !t.isShattered) {
                    this.release(t);
                    this.damageNumbers.splice(i, 1);
                }
            }
        }

        let vx = 0, vy = 0, life = TEXT_LIFESPAN;
        if (type === 'SHOUT') {
            // SHOUT 的生命週期現在由詠唱時間決定
            const safeDuration = Math.min(5.0, duration > 0 ? duration : 1.0);
            life = safeDuration + 0.5;
            if (isUlt) { vy = -5; size = 24; }
            else { vy = -20; size = 14; }
        } else if (type === 'CC') {
            vy = -20; life = 1.5;
        } else if (type === 'KILL_STREAK') {
            vx = 0; vy = -30; life = 3.5; size = 32; 
        } else {
            vx = (Math.random() - 0.5) * 60; vy = -100; 
        }

        let ft = this.pool.length > 0 ? this.pool.pop()! : this.createEmpty();
        ft.active = true;
        ft.x = x; ft.y = y; ft.vx = vx; ft.vy = vy;
        ft.text = text; ft.color = color;
        ft.life = life; ft.maxLife = life;
        ft.size = size; ft.type = type;
        ft.isUlt = isUlt;
        ft.ownerId = ownerId;
        ft.isShattered = false;
        ft.rotation = 0;
        ft.vRot = 0;
        ft.time = 0;
        ft.totalDuration = duration > 0 ? duration : 1.0; 
        ft.cachedWidth = undefined; 

        this.damageNumbers.push(ft);
    }

    public breakCastText(ownerId: string) {
        const text = this.damageNumbers.find(t => t.type === 'SHOUT' && t.ownerId === ownerId && !t.isShattered);

        if (text) {
            text.isShattered = true;
            text.color = '#94a3b8'; 
            text.vy = -180; 
            text.vx = (Math.random() - 0.5) * 250; 
            text.vRot = (Math.random() - 0.5) * 20; 
            text.life = 0.5; 
            text.maxLife = 0.5;
        }
    }

    private release(ft: FloatingText) {
        ft.active = false;
        ft.ownerId = undefined;
        this.pool.push(ft);
    }

    public update(dt: number) {
        for (let i = this.damageNumbers.length - 1; i >= 0; i--) { 
            const d = this.damageNumbers[i]; 
            d.life -= dt; 
            d.time += dt;

            d.x += d.vx * dt;
            d.y += d.vy * dt; 
            d.rotation += d.vRot * dt; 

            if (d.type === 'DAMAGE' || d.type === 'HEAL' || d.isShattered) {
                const g = d.isShattered ? GRAVITY * 3.0 : GRAVITY;
                d.vy += g * dt;
            }
            else if (d.type === 'SHOUT' || d.type === 'CC') d.vy *= 0.95; 
            else if (d.type === 'KILL_STREAK') d.vy *= 0.92; 

            if (d.life <= 0) {
                this.release(d);
                this.damageNumbers.splice(i, 1); 
            }
        }
    }
}

import { HUDSystem } from "../../systems/hud";

export const TextPainter = {

    drawFloatingText(ctx: CanvasRenderingContext2D, hud: HUDSystem) {
        const textCount = hud.damageNumbers.length;
        if (textCount === 0) return;

        ctx.textAlign = 'center';
        ctx.textBaseline = 'middle';
        ctx.shadowBlur = 0; 

        hud.damageNumbers.forEach(d => {
            if (!d.active) return;

            const lifePct = d.life / d.maxLife;
            // Early cull for nearly invisible text
            if (lifePct <= 0.05) return;

            const alpha = d.isShattered ? lifePct : (lifePct < 0.3 ? lifePct / 0.3 : 1.0);
            ctx.globalAlpha = alpha;

            ctx.save();
            ctx.translate(d.x, d.y);

            if (d.rotation !== 0) ctx.rotate(d.rotation);

            if (d.isShattered) {
                const shatterProgress = 1 - lifePct;
                const scale = 1.0 + shatterProgress * 0.6;
                ctx.scale(scale, scale);
                ctx.translate((Math.random()-0.5)*4, (Math.random()-0.5)*4);
            } else if (d.type === 'SHOUT') {
                const floatY = Math.sin(d.time * 6) * 3;
                ctx.translate(0, floatY);
            }

            if (d.type === 'KILL_STREAK') {
                const pop = Math.min(1, (1 - lifePct) * 5); 
                const pulse = 1 + Math.sin(lifePct * 10) * 0.1;
                const scale = pop * pulse * 1.5; 
                ctx.scale(scale, scale);
                ctx.font = `900 italic ${d.size}px "Arial Black", sans-serif`;

                ctx.lineWidth = 4;
                ctx.lineJoin = 'round';
                ctx.strokeStyle = '#000';
                ctx.strokeText(d.text, 0, 0);
                ctx.fillStyle = d.color;
                ctx.fillText(d.text, 0, 0);

            } else if (d.type === 'SHOUT') {
                // [OPTIMIZATION] Cache Width
                if (d.cachedWidth === undefined) {
                    ctx.font = d.isUlt ? `900 italic ${d.size}px "Arial Black", sans-serif` : `bold ${d.size}px "Segoe UI", sans-serif`;
                    d.cachedWidth = ctx.measureText(d.text).width;
                }

                const w = d.isUlt ? (d.cachedWidth! / 2 + 35) : d.cachedWidth!;
                const h = d.size + (d.isUlt ? 14 : 8);

                ctx.font = d.isUlt ? `900 italic ${d.size}px "Arial Black", sans-serif` : `bold ${d.size}px "Segoe UI", sans-serif`;

                if (d.isUlt) {
                    const scale = 1 + (1 - lifePct) * 0.1; 
                    ctx.scale(scale, scale);

                    if (d.isShattered) {
                        ctx.fillStyle = 'rgba(20, 0, 0, 0.5)';
                        ctx.fillRect(-w - 20, -h/2, w*2 + 40, h);

                        ctx.strokeStyle = '#ef4444';
                        ctx.lineWidth = 2;
                        ctx.beginPath(); ctx.moveTo(-w, -h/2); ctx.lineTo(0, -h/2); ctx.stroke();
                        ctx.beginPath(); ctx.moveTo(w, h/2); ctx.lineTo(0, h/2); ctx.stroke();

                        ctx.fillStyle = '#94a3b8';
                        ctx.fillText(d.text, 0, 0);
                    } else {
                        // Background
                        ctx.fillStyle = 'rgba(0,0,0,0.6)';
                        ctx.fillRect(-w - 40, -h/2 - 4, w*2 + 80, h + 8);

                        // Borders
                        ctx.strokeStyle = d.color;
                        ctx.lineWidth = 2; 
                        ctx.beginPath();
                        ctx.moveTo(-w - 10, -h/2); ctx.lineTo(w + 10, -h/2);
                        ctx.moveTo(-w - 10, h/2); ctx.lineTo(w + 10, h/2);
                        ctx.stroke();

                        ctx.fillStyle = d.color;
                        ctx.fillRect(-w - 25, -5, 4, 10); // Left dot
                        ctx.fillRect(w + 21, -5, 4, 10);  // Right dot

                        // Text
                        ctx.lineWidth = 3;
                        ctx.strokeStyle = '#000';
                        ctx.strokeText(d.text, 0, 0);

                        const progress = Math.min(1.0, d.time / d.totalDuration);

                        if (progress >= 1.0) {
                            ctx.fillStyle = '#ffffff';
                            ctx.fillText(d.text, 0, 0);
                        } else {
                            // Dim Text
                            ctx.fillStyle = 'rgba(255,255,255,0.5)';
                            ctx.fillText(d.text, 0, 0);

                            // Progress Bar at bottom (No CLIP!)
                            const barW = (w * 2 + 60) * progress;
                            ctx.fillStyle = d.color;
                            ctx.fillRect(-w - 30, h/2 + 2, barW, 3);
                        }
                    }

                } else {
                    // Normal Shout
                    const boxW = w + 20;
                    const boxH = h;

                    if (d.isShattered) {
                        ctx.fillStyle = 'rgba(30, 30, 30, 0.6)'; 
                        ctx.fillRect(-boxW/2, -boxH/2, boxW, boxH);
                        ctx.strokeStyle = 'rgba(255,50,50,0.3)';
                        ctx.lineWidth = 1;
                        ctx.strokeRect(-boxW/2, -boxH/2, boxW, boxH);
                        ctx.fillStyle = '#94a3b8'; 
                        ctx.fillText(d.text, 0, 0);
                    } else {
                        ctx.fillStyle = 'rgba(15, 23, 42, 0.8)';
                        ctx.fillRect(-boxW/2, -boxH/2, boxW, boxH);

                        ctx.strokeStyle = d.color;
                        ctx.lineWidth = 1;
                        ctx.strokeRect(-boxW/2, -boxH/2, boxW, boxH);

                        const progress = Math.min(1.0, d.time / d.totalDuration);

                        if (progress >= 1.0) {
                            ctx.fillStyle = '#ffffff'; 
                            ctx.fillText(d.text, 0, 0);
                        } else {
                            // Dim Text
                            ctx.fillStyle = 'rgba(255,255,255,0.6)'; 
                            ctx.fillText(d.text, 0, 0);
                            // Progress Bar (Simple Underline)
                            const fillW = boxW * progress;
                            ctx.fillStyle = '#fff';
                            ctx.fillRect(-boxW/2, boxH/2 - 2, fillW, 2);
                        }
                    }
                }

            } else {
                ctx.font = `900 ${d.size}px "Segoe UI", sans-serif`;
                ctx.lineWidth = 3;
                ctx.strokeStyle = 'rgba(0,0,0,0.8)';
                ctx.strokeText(d.text, 0, 0);
                ctx.fillStyle = d.color; 
                ctx.fillText(d.text, 0, 0);
            }

            ctx.restore();
            ctx.globalAlpha = 1.0;
        });
    }
};

