import { Agent, GameEngine, VICTORY_PHASE_DURATION } from "../game";
import { Camera, GameRenderer } from "../renderer"; 
import { Hex, Skill } from "../../types";
import { BackgroundRenderer } from "./background";
import { TacticalRenderer } from "./tactical";
import { HUDRenderer } from "./HUDRenderer";
import { PostProcessor } from "./PostProcessor"; 
import { RenderList } from "./RenderList";
import { RenderDispatcher } from "./RenderDispatcher";

export class RenderPipeline {
    private renderer: GameRenderer;
    private background = new BackgroundRenderer();
    private tactical = new TacticalRenderer();
    private hud = new HUDRenderer();
    private post = new PostProcessor();
    private renderList = new RenderList();

    // Transition State managed internally (SSOT)
    private transitionT: number = 0;
    private transitionPhase: 'IN' | 'OUT' | 'IDLE' = 'IDLE';

    constructor(renderer: GameRenderer) { 
        this.renderer = renderer; 
    }

    public setTransitionPhase(phase: 'IN' | 'OUT' | 'IDLE') {
        if (this.transitionPhase !== phase) {
            this.transitionPhase = phase;
            // Reset progress when phase changes, unless going to IDLE
            if (phase !== 'IDLE') {
                this.transitionT = 0;
            }
        }
    }

    public update(dt: number, engine: GameEngine) { 
        this.tactical.update(dt, engine); 

        // Animation Logic moved from GameCanvas to here
        if (this.transitionPhase !== 'IDLE') {
            // Slower, weightier transition speed
            const speed = 0.5; 
            this.transitionT = Math.min(1.0, this.transitionT + dt * speed);
        } else {
            this.transitionT = 0;
        }
    }

    public draw(ctx: CanvasRenderingContext2D, engine: GameEngine, camera: Camera, highlight: Agent | null, fps: number, hoveredHex: Hex | null, hoveredSkill: Skill | null, battleTime: number, realTime: number): void {
        const { width: pW, height: pH } = ctx.canvas;
        if (pW === 0 || pH === 0) return;

        const dpr = window.devicePixelRatio || 1;
        const [lW, lH] = [pW / dpr, pH / dpr];
        const { mapConfig: cfg, currentScene: sc } = engine;

        // 1. Clear & Background
        ctx.resetTransform(); 
        ctx.fillStyle = '#020617'; 
        ctx.fillRect(0, 0, pW, pH);
        ctx.scale(dpr, dpr);
        // Background uses RealTime for ambient effects (stars, fog) even when game paused
        this.background.draw(ctx, lW, lH, sc, cfg, realTime);

        // 2. Main Scene (World Space)
        ctx.save();
        this.renderer.camera.sync(camera); 
        this.renderer.camera.applyTransform(ctx, lW, lH);
        // World objects use BattleTime to sync with logic
        this.drawWorld(ctx, engine, camera, highlight, hoveredHex, hoveredSkill, battleTime);
        ctx.restore(); 

        // 3. Post Processing
        let transAb = (this.transitionPhase !== 'IDLE') ? 4 * this.transitionT * (1 - this.transitionT) * 0.5 : 0;
        this.post.apply(ctx, pW, pH, this.renderer.camera.getTrauma(), transAb);

        // 4. Overlays (Screen/World Hybrid)
        ctx.save(); 
        this.renderer.camera.applyTransform(ctx, lW, lH);
        this.tactical.drawOverlay(ctx, engine, highlight, this.renderer.grid, realTime);
        this.hud.draw(ctx, this.renderer.hud, engine.agents, (q, r) => this.renderer.grid.getTerrainHeight(q, r, engine), cfg, highlight, battleTime);
        ctx.restore(); 

        if (engine.directorTargetId) this.tactical.drawHUD(ctx, engine, lW, lH, camera, realTime);
        this.tactical.drawDebug(ctx, fps);

        // 5. Global Transition/Finish Blur
        let blur = engine.victory.isFinishing ? 1.0 - (engine.victory.victoryTimer / VICTORY_PHASE_DURATION) : (engine.victory.winningTeam !== null ? 1.0 : 0);
        if (this.transitionPhase === 'OUT') blur = 1.0; 
        else if (this.transitionPhase === 'IN') blur = 1.0 - this.transitionT;
        if (blur > 0) this.post.applyFinishBlur(ctx, pW, pH, Math.max(0, Math.min(1, blur)));
    }

    private drawWorld(ctx: CanvasRenderingContext2D, engine: GameEngine, camera: Camera, highlight: Agent | null, hoveredHex: Hex | null, hoveredSkill: Skill | null, t: number) {
        this.renderList.reset();
        const terrainH = (q: number, r: number) => this.renderer.grid.getTerrainHeight(q, r, engine);
        const lW = ctx.canvas.width / (window.devicePixelRatio || 1);
        const lH = ctx.canvas.height / (window.devicePixelRatio || 1);

        this.renderer.grid.submitRenderables(this.renderList, engine, hoveredHex, hoveredSkill, highlight, engine.projectiles, this.transitionT, this.transitionPhase, t);
        this.renderer.vfxRenderer.submitRenderables(this.renderList, engine, this.renderer.vfx, terrainH, engine.mapConfig, this.transitionT, this.transitionPhase, { width: lW, height: lH, camera });
        this.renderer.unit.submitRenderables(this.renderList, engine.agents, terrainH, t, highlight, engine.mapConfig);

        this.renderList.sort();
        for (let i = 0; i < this.renderList.count; i++) {
            RenderDispatcher.dispatch(ctx, this.renderList.ops[i], engine.mapConfig.layout, t, this.renderer.unit);
        }

        const occluded = this.renderer.grid.getOccludedAgents(engine);
        if (occluded.length > 0) {
            ctx.save();
            occluded.forEach(a => this.renderer.unit.drawSilhouette(ctx, a, terrainH, t, engine.mapConfig));
            ctx.restore();
        }

        // [FIX] Pass layout to StatusOrchestrator
        this.renderer.statusOrchestrator.draw(ctx, engine.agents, t, terrainH, engine.mapConfig.layout);
    }
}

import { RenderOp, RenderOpType } from "./RenderList";
import { TerrainRenderer } from "./grid/TerrainRenderer";
import { GridOverlays } from "./grid/GridOverlays";
import { HazardPainter } from "./grid/painters/HazardPainter";
import { SpriteManager } from "../sprites";
import { ParticleRenderer } from "../systems/vfx/renderers/ParticleRenderer";
import { ProjectileDrawer } from "./ProjectileDrawer";
import { AssetManager } from "../assets";
import { ENV_ANCHOR_X, ENV_ANCHOR_Y } from "../graphics/EnvironmentFactory";
import { HexLayout } from "../../types";
import { UnitRenderSystem } from "../systems/unit";

export class RenderDispatcher {
    public static dispatch(
        ctx: CanvasRenderingContext2D, 
        op: RenderOp, 
        layout: HexLayout, 
        globalTime: number,
        unitRenderer: UnitRenderSystem
    ) {
        const snapX = Math.round(op.tx);
        const snapY = Math.round(op.ty);

        switch (op.type) {
            case RenderOpType.TERRAIN:
                TerrainRenderer.drawBlock(ctx, snapX, snapY, op.tsize, op.th, op.ttheme, op.ttype, globalTime, layout);
                TerrainRenderer.drawTerrainDetail(ctx, snapX, snapY, op.th, op.ttype, op.tdetail, op.tq, op.tr, globalTime, layout, op.ttheme);
                // SSOT: Height-based projection inside
                GridOverlays.drawOverlays(ctx, snapX, snapY, op.th, op.tsize, op.oStatus, op.oDanger, op.oLightCol, op.oLightInt, op.oRange, op.oRangeCol, op.oHover, op.oHasUnit, op.tq, op.tr, op.time, layout);
                break;

            case RenderOpType.HAZARD: 
                // [FIX] Pass layout to HazardPainter
                if (op.oHazard) HazardPainter.draw(ctx, snapX, snapY, op.oHazard, op.time, layout);
                break;

            case RenderOpType.OBSTACLE:
                ctx.drawImage(SpriteManager.getObstacleSprite(op.ttype, layout), snapX - ENV_ANCHOR_X, snapY - ENV_ANCHOR_Y);
                break;

            case RenderOpType.UNIT:
                if (op.agent) unitRenderer.drawAssembly(ctx, op.agent, snapX, snapY, op.time, op.uSelected, op.uSilhouette, layout);
                break;

            case RenderOpType.DECAL:
                ctx.save();
                ctx.translate(snapX, snapY);
                ctx.scale(op.dScale, op.dScale);
                ctx.globalAlpha = Math.min(1, op.dLife);
                ctx.drawImage(AssetManager.getBlastZone(op.dColor), -64, -32, 128, 64);
                ctx.restore();
                break;

            case RenderOpType.VFX:
                if (op.particle) {
                    ctx.save();
                    ctx.translate(snapX, snapY);
                    ParticleRenderer.drawSingleParticle(ctx, op.particle, 0, 0, op.vProgress, op.vChaos, layout);
                    ctx.restore();
                }
                break;

            case RenderOpType.PROJECTILE:
                ProjectileDrawer.draw(ctx, op, globalTime);
                break;
        }
    }
}

import { GroundHazard, HexLayout } from "../../../../../types";
import { HEX_SIZE, ISO_SCALE_Y } from "../../../../../constants";
import { HAZARD_VISUALS } from "../../../../../data/vfx/hazard_visuals";
import { VFXFactory } from "../../../graphics/VFXFactory";
import { SurfacePainter } from "../../../graphics/painters/SurfacePainter";
import { VolumePainter } from "../../../graphics/painters/VolumePainter";
import { VisualMath } from "../../../math/VisualMath";

export const HazardPainter = {
    draw(ctx: CanvasRenderingContext2D, x: number, y: number, hazard: GroundHazard, globalTime: number, layout: HexLayout) {
        const def = HAZARD_VISUALS[hazard.type] || HAZARD_VISUALS['GENERIC'];
        // Smooth fade out at end of duration
        let fade = hazard.duration < 0.8 ? hazard.duration / 0.8 : 1.0;

        ctx.save();
        ctx.globalAlpha = fade;
        const drawY = VisualMath.applyLayerBias(y, 'HAZARD');

        if (def.type === 'FOG') {
            const texture = VFXFactory.getTexture('SMOKE', def.primaryColor);
            const speed = globalTime * def.speed;

            // VOLUMETRIC STACKING (3 Layers)
            // Draw multiple layers at different Y offsets to simulate 3D volume
            const layers = 3;
            const baseSize = HEX_SIZE * 3.5;

            for(let i = 0; i < layers; i++) {
                const layerProgress = i / (layers - 1); // 0.0 to 1.0

                // Higher layers are drawn "higher" (smaller Y in screen space)
                // -25px total height variance
                const layerY = drawY - (i * 12); 

                // Parallax scale: Top layers slightly larger and more transparent
                const scale = 1.0 + (i * 0.1) + Math.sin(speed + i) * 0.05;
                const size = baseSize * scale;

                ctx.save();
                ctx.translate(x, layerY + VisualMath.Z_LAYERS.HAZARD_FOG);
                ctx.scale(1, ISO_SCALE_Y);

                // Rotation variance per layer creates depth
                const rotation = (i % 2 === 0 ? 1 : -1) * (speed * (0.1 + i * 0.05)) + i;
                ctx.rotate(rotation);

                if (i === 0) {
                    // Base Layer: Darker, Grounded
                    ctx.globalCompositeOperation = 'source-over';
                    ctx.globalAlpha = def.intensity * 0.6 * fade;
                } else if (i === 1) {
                    // Mid Layer: Body
                    ctx.globalCompositeOperation = 'source-over';
                    ctx.globalAlpha = def.intensity * 0.4 * fade;
                } else {
                    // Top Layer: Highlights/Wisps
                    ctx.globalCompositeOperation = 'screen';
                    ctx.globalAlpha = def.intensity * 0.3 * fade;
                }

                ctx.drawImage(texture, -size/2, -size/2, size, size);
                ctx.restore();
            }
        }
        else if (def.type === 'LIQUID') {
            const speed = globalTime * def.speed;
            const intensity = def.intensity * (0.85 + Math.sin(speed * 0.8) * 0.15);
            const liquidY = drawY + VisualMath.Z_LAYERS.LIQUID_OFFSET;

            // Draw base liquid with correct layout
            SurfacePainter.drawLiquid(ctx, x, liquidY, def.primaryColor, speed, Math.min(1.0, intensity * 1.2), layout);

            if (def.cracks) SurfacePainter.drawCracks(ctx, x, liquidY, def.secondaryColor, intensity);

            // Enhanced Fire Visuals
            if (hazard.type === 'FIRE') {
                const flameTex = VFXFactory.getTexture('SMOKE', '#fca5a5');
                const glowTex = VFXFactory.getTexture('GLOW', '#f97316');

                // 1. Core Glow (Ground)
                ctx.save();
                ctx.translate(x, liquidY);
                ctx.scale(1, ISO_SCALE_Y);
                ctx.globalCompositeOperation = 'screen';
                ctx.globalAlpha = 0.6 * fade;
                const glowSize = HEX_SIZE * 2.5 + Math.sin(globalTime * 10) * 10;
                ctx.drawImage(glowTex, -glowSize/2, -glowSize/2, glowSize, glowSize);
                ctx.restore();

                // 2. Rising Flame Tongues (Volumetric)
                const flameCount = 3;
                for(let i=0; i<flameCount; i++) {
                    const offset = i * (Math.PI * 2 / flameCount);
                    const cycle = (globalTime * 1.5 + offset) % 1; // 0 to 1 loop

                    const riseH = cycle * 80; // Height
                    const wiggle = Math.sin(globalTime * 5 + i) * 15;

                    const scaleBase = 1.0 - cycle; // Shrink as rising
                    const scaleY = 1.5 + Math.sin(globalTime * 10) * 0.5; // Flicker stretch

                    ctx.save();
                    ctx.translate(x + wiggle, liquidY - riseH);
                    ctx.scale(scaleBase, scaleBase * scaleY);

                    ctx.globalCompositeOperation = 'lighter';
                    ctx.globalAlpha = (1.0 - cycle) * intensity * fade;

                    const fSize = 60;
                    ctx.drawImage(flameTex, -fSize/2, -fSize/2, fSize, fSize);
                    ctx.restore();
                }
            }
        }
        else if (def.type === 'CRYSTAL') {
            if (def.extrude) VolumePainter.drawExtrusion(ctx, x, drawY, HEX_SIZE * 0.8, 8, def.primaryColor, 0.7, layout);
            ctx.save();
            ctx.translate(x, drawY - 5); ctx.scale(1, ISO_SCALE_Y);
            ctx.globalCompositeOperation = 'screen'; ctx.globalAlpha = 0.6;
            ctx.drawImage(VFXFactory.getTexture('ROCK', def.secondaryColor), -15, -15, 30, 30);
            ctx.restore();
        }
        else if (def.type === 'VOID_HOLE') {
            const r = HEX_SIZE * 1.6;
            ctx.save();
            ctx.translate(x, drawY); ctx.scale(1, ISO_SCALE_Y);
            ctx.globalCompositeOperation = 'source-over'; ctx.fillStyle = '#000';
            ctx.beginPath(); ctx.arc(0, 0, r * 0.7, 0, Math.PI*2); ctx.fill();

            ctx.globalCompositeOperation = 'lighter'; 
            ctx.lineWidth = 4; 
            ctx.strokeStyle = def.secondaryColor;
            ctx.shadowColor = def.secondaryColor; 
            ctx.shadowBlur = 20;

            ctx.rotate(globalTime * 3);
            ctx.beginPath();
            for(let i=0; i<3; i++) {
                const ang = i * (Math.PI*2/3); ctx.moveTo(0,0);
                ctx.quadraticCurveTo(Math.cos(ang)*r, Math.sin(ang)*r, Math.cos(ang+1)*r, Math.sin(ang+1)*r);
            }
            ctx.stroke();
            ctx.restore();
        }
        ctx.restore();
    }
};

import { Agent } from "../../game";
import { ShieldPainter } from "./painters/ShieldPainter";
import { OverheadPainter } from "./painters/OverheadPainter";
import { GroundEffectPainter } from "./painters/GroundEffectPainter";
import { StateModelPainter } from "./painters/StateModelPainter";
import { VisualMath } from "../../math/VisualMath";
import { HexLayout } from "../../../types";

/**
 * ECS Status Orchestrator v11.6
 * 負責所有單位狀態特效的座標解算與渲染分發
 */
export class StatusOrchestrator {

    public draw(
        ctx: CanvasRenderingContext2D, 
        agents: Agent[], 
        globalTime: number,
        getTerrainHeight: (q: number, r: number) => number,
        layout: HexLayout = 'FLAT'
    ) {
        for (const agent of agents) {
            // 跳過已徹底消失的單位
            if (agent.hp <= 0 && agent.fullyDead) continue;

            // 基礎幾何解算 (SSOT)
            const px = agent.px + agent.physics.x;
            const py = agent.py + agent.physics.y;
            const pz = agent.physics.z;

            const terrainH = getTerrainHeight(agent.q, agent.r);
            const visualFloorY = py - terrainH; 

            // 核心數學：解算身體中心點（用於護盾與包裹類特效）
            const bodyCenterY = VisualMath.getVisualBodyCenterY(visualFloorY, pz);

            // 1. 放逐/凝滯 (最高級狀態覆蓋)
            if (agent.banished) {
                StateModelPainter.drawBanishment(ctx, agent, px, bodyCenterY, globalTime);
                continue; // 處於放逐狀態時通常不顯示其他 UI 特效
            }

            // 2. 地面鎖定效果 (Root/Burning)
            // 強制腳底偏置：-5px 確保在地板之上且在 Token 之下
            GroundEffectPainter.draw(ctx, agent, px, visualFloorY - pz, globalTime, layout);

            // 3. 護盾 (Volumetric Shell)
            // 護盾必須跟隨 bodyCenterY
            ShieldPainter.draw(ctx, agent, px, bodyCenterY, globalTime, layout);

            // 4. 頭頂狀態圖標 (Floating HUD)
            // 圖標高度 = 中心點 - 模型高度偏移
            OverheadPainter.draw(ctx, agent, px, bodyCenterY, globalTime);
        }
    }
}

import { Agent } from "../../../../game";
import { ISO_SCALE_Y } from "../../../../../constants";
import { VolumePainter } from "../../../graphics/painters/VolumePainter";
import { HexGeometry } from "../../../graphics/utils/HexGeometry";
import { HexLayout } from "../../../../../types";

// 數學規範：CC 地面層偏置量
const CC_GROUND_BIAS = -5;

export const GroundEffectPainter = {
    /**
     * 繪製單位身上的持續性 CC 特效 (地面 -> 身體)
     * @param y 單位目前的視覺腳底高度 (含物理 Z)
     */
    draw(ctx: CanvasRenderingContext2D, agent: Agent, x: number, y: number, t: number, layout: HexLayout) {
        const groundY = y + CC_GROUND_BIAS;

        // 1. 禁錮效果 (Root / Vines)
        if (agent.rootTimer > 0) {
            const color = '#fbbf24'; 
            ctx.save();
            ctx.translate(x, groundY);

            const pulse = 0.8 + Math.sin(t * 12) * 0.15;
            const r = 24 * pulse;

            // A. 底層能量環
            ctx.strokeStyle = color;
            ctx.lineWidth = 2;
            ctx.globalAlpha = 0.8;
            ctx.shadowColor = color;
            ctx.shadowBlur = 10;
            // [FIX] Use layout
            HexGeometry.traceHex(ctx, 0, 0, r, true, layout);
            ctx.stroke();

            // B. 3D 突刺 (幾何模擬)
            ctx.fillStyle = color;
            ctx.globalCompositeOperation = 'source-over';
            const count = 3;
            for(let i=0; i<count; i++) {
                const angle = i * (Math.PI*2/count) + t * 2;
                const sx = Math.cos(angle) * (r * 0.7);
                const sy = Math.sin(angle) * (r * 0.7) * ISO_SCALE_Y;

                ctx.beginPath();
                ctx.moveTo(sx, sy);
                ctx.lineTo(sx, sy - 25); 
                ctx.lineTo(sx + 6, sy + 2);
                ctx.fill();
            }
            ctx.restore();
        }

        // 2. 持續傷害 (DoT) - 顯眼的上升氣流
        if (agent.dotTimer > 0 && agent.dotDmg > 0) {
            // Determine color based on hazard guessing (Green for generic/poison, Red for fire)
            const color = '#a3e635'; // Lime Green default
            const secondary = '#4d7c0f';

            ctx.save();
            ctx.translate(x, groundY);

            // Floor Puddle
            ctx.globalCompositeOperation = 'source-over';
            ctx.fillStyle = secondary;
            ctx.globalAlpha = 0.6;
            ctx.beginPath(); 
            ctx.ellipse(0, 0, 20, 10, 0, 0, Math.PI*2); 
            ctx.fill();

            // Rising Fumes (Vertical Lines around body)
            ctx.strokeStyle = color;
            ctx.lineWidth = 2;
            ctx.lineCap = 'round';
            ctx.globalCompositeOperation = 'screen';

            const strands = 4;
            const height = 60;

            for(let i=0; i<strands; i++) {
                const offset = i * (Math.PI * 2 / strands);
                const loopT = (t * 2 + offset) % 1; // 0 to 1
                const curH = loopT * height;
                const fade = Math.sin(loopT * Math.PI); // Fade in/out

                const wave = Math.sin(t * 5 + curH * 0.1) * 5;
                const rx = Math.cos(offset) * 15 + wave;
                const ry = Math.sin(offset) * 15 * ISO_SCALE_Y;

                ctx.globalAlpha = fade;
                ctx.beginPath();
                ctx.moveTo(rx, ry - curH);
                ctx.lineTo(rx, ry - curH - 15); // Length of fume
                ctx.stroke();
            }
            ctx.restore();
        }

        // 3. 持續恢復 (HoT) - 上升十字/光點
        if (agent.hotTimer > 0) {
            const color = '#86efac'; // Bright Green/Mint

            ctx.save();
            ctx.translate(x, groundY);

            // Floor Glow
            ctx.fillStyle = color;
            ctx.globalAlpha = 0.3;
            ctx.globalCompositeOperation = 'screen';
            ctx.beginPath(); ctx.ellipse(0, 0, 20, 10, 0, 0, Math.PI*2); ctx.fill();

            // Spiraling Energy
            const particles = 3;
            const height = 70;

            for(let i=0; i<particles; i++) {
                const offset = i * (Math.PI * 2 / particles);
                const loopT = (t * 1.5 + offset) % 1;
                const curH = loopT * height;
                const fade = 1.0 - Math.pow(Math.abs(loopT - 0.5) * 2, 2); // Smooth bell curve fade

                const angle = t * 4 + curH * 0.1;
                const radius = 20 * (1 - loopT * 0.5); // Taper in

                const px = Math.cos(angle) * radius;
                const py = Math.sin(angle) * radius * ISO_SCALE_Y;

                ctx.globalAlpha = fade;
                ctx.fillStyle = color;

                // Draw Plus Sign or Dot
                ctx.save();
                ctx.translate(px, py - curH);
                ctx.fillRect(-2, -6, 4, 12);
                ctx.fillRect(-6, -2, 12, 4);
                ctx.restore();
            }
            ctx.restore();
        }
    }
};

import { Agent } from "../../../../game";
import { Team, HexLayout } from "../../../../../types";
import { VolumePainter } from "../../../graphics/painters/VolumePainter";

export const ShieldPainter = {
    /**
     * 繪製包裹單位的能量護盾
     * @param y 單位視覺中心 Y 軸
     */
    draw(ctx: CanvasRenderingContext2D, agent: Agent, x: number, y: number, t: number, layout: HexLayout) {
        if (agent.shield <= 0) return;

        const isBlue = agent.team === Team.BLUE;
        const color = isBlue ? '#60a5fa' : '#ef4444';

        // 護盾強度視覺映射
        const pct = Math.min(1, agent.shield / (agent.maxShield || 100));

        // Increased visibility: Base pulse 0.3 -> 0.5
        const pulse = 0.3 + (pct * 0.4) + Math.sin(t * 5) * 0.1;

        ctx.save();
        ctx.translate(x, y); 

        // 使用 3D 稜柱繪製體積感
        // 向上抬升一半高度以實現垂直居中
        const shieldH = 80;
        const shieldR = 38;

        ctx.globalCompositeOperation = 'screen';
        // [FIX] Pass layout to VolumePainter
        VolumePainter.draw3DPrism(ctx, 0, shieldH/2, shieldR, shieldH, color, pulse, 'GRADIENT_FADE', layout);

        // 邊緣掃描線 (TA 效果) - Enhanced with double scanlines
        ctx.strokeStyle = '#ffffff';
        ctx.lineWidth = 2; // Thicker lines

        // Primary Scanline
        ctx.globalAlpha = Math.min(1, pulse * 1.2);
        const scanLineY1 = (t * 120) % shieldH - shieldH/2;
        ctx.beginPath();
        ctx.moveTo(-shieldR * 0.9, scanLineY1);
        ctx.lineTo(shieldR * 0.9, scanLineY1);
        ctx.stroke();

        // Secondary Scanline (Offset, fainter)
        ctx.globalAlpha = Math.min(1, pulse * 0.6);
        const scanLineY2 = ((t * 120 + shieldH * 0.5) % shieldH) - shieldH/2;
        ctx.beginPath();
        ctx.moveTo(-shieldR * 0.7, scanLineY2);
        ctx.lineTo(shieldR * 0.7, scanLineY2);
        ctx.stroke();

        // Shield Top/Bottom Caps for definition
        ctx.globalAlpha = 0.4;
        ctx.lineWidth = 1;
        ctx.strokeStyle = color;
        ctx.beginPath();
        ctx.ellipse(0, -shieldH/2, shieldR, shieldR*0.5, 0, 0, Math.PI*2);
        ctx.stroke();
        ctx.beginPath();
        ctx.ellipse(0, shieldH/2, shieldR, shieldR*0.5, 0, 0, Math.PI*2);
        ctx.stroke();

        ctx.restore();
    }
};

const GRAVITY = 200;
const TEXT_LIFESPAN = 1.0;
const MAX_ACTIVE_TEXTS = 60; // Reduced for performance safety

export interface FloatingText {
    active: boolean;
    x: number; 
    y: number;
    vx: number; 
    vy: number;
    text: string; 
    color: string;
    life: number; 
    maxLife: number;
    size: number;
    type: 'DAMAGE' | 'HEAL' | 'SHOUT' | 'CC' | 'KILL_STREAK';
    isUlt: boolean; 

    // New Props for Breakable Text
    ownerId?: string;      // 用於綁定單位
    isShattered?: boolean; // 標記是否已被打斷
    rotation: number;      // 物理旋轉角度
    vRot: number;          // 旋轉速度

    // Animation Timer
    time: number;          // 存活時間 (累加)
    totalDuration: number; // 預計總詠唱時間 (用於進度條計算)
    cachedWidth?: number;  // Cached width for text measurement optimization
}

export class HUDSystem {
    public damageNumbers: FloatingText[] = [];
    private pool: FloatingText[] = [];

    constructor() {
        for(let i=0; i<50; i++) this.pool.push(this.createEmpty());
    }

    public reset() {
        for (const d of this.damageNumbers) this.release(d);
        this.damageNumbers.length = 0;
    }

    private createEmpty(): FloatingText {
        return {
            active: false,
            x: 0, y: 0, vx: 0, vy: 0,
            text: '', color: '#fff', life: 0, maxLife: 0, size: 0,
            type: 'DAMAGE', isUlt: false,
            ownerId: undefined, isShattered: false, rotation: 0, vRot: 0,
            time: 0, totalDuration: 0, cachedWidth: undefined
        };
    }

    public addFloatingText(
        x: number, y: number, text: string, color: string, size: number, 
        type: 'DAMAGE' | 'HEAL' | 'SHOUT' | 'CC' | 'KILL_STREAK' = 'DAMAGE', 
        isUlt: boolean = false,
        ownerId?: string,
        duration: number = 0
    ) {
        if (this.damageNumbers.length >= MAX_ACTIVE_TEXTS) {
            const old = this.damageNumbers.shift();
            if (old) this.release(old);
        }

        // Kill Streak 清理邏輯
        if (type === 'KILL_STREAK') {
            for (let i = this.damageNumbers.length - 1; i >= 0; i--) {
                if (this.damageNumbers[i].type === 'KILL_STREAK') {
                    this.release(this.damageNumbers[i]);
                    this.damageNumbers.splice(i, 1);
                }
            }
        }

        // 如果該單位已有存在的 SHOUT，先移除舊的 (避免重疊)
        if (type === 'SHOUT' && ownerId) {
            for (let i = this.damageNumbers.length - 1; i >= 0; i--) {
                const t = this.damageNumbers[i];
                if (t.type === 'SHOUT' && t.ownerId === ownerId && !t.isShattered) {
                    this.release(t);
                    this.damageNumbers.splice(i, 1);
                }
            }
        }

        let vx = 0, vy = 0, life = TEXT_LIFESPAN;
        if (type === 'SHOUT') {
            // SHOUT 的生命週期現在由詠唱時間決定
            const safeDuration = Math.min(5.0, duration > 0 ? duration : 1.0);
            life = safeDuration + 0.5;
            if (isUlt) { vy = -5; size = 24; }
            else { vy = -20; size = 14; }
        } else if (type === 'CC') {
            vy = -20; life = 1.5;
        } else if (type === 'KILL_STREAK') {
            vx = 0; vy = -30; life = 3.5; size = 32; 
        } else {
            vx = (Math.random() - 0.5) * 60; vy = -100; 
        }

        let ft = this.pool.length > 0 ? this.pool.pop()! : this.createEmpty();
        ft.active = true;
        ft.x = x; ft.y = y; ft.vx = vx; ft.vy = vy;
        ft.text = text; ft.color = color;
        ft.life = life; ft.maxLife = life;
        ft.size = size; ft.type = type;
        ft.isUlt = isUlt;
        ft.ownerId = ownerId;
        ft.isShattered = false;
        ft.rotation = 0;
        ft.vRot = 0;
        ft.time = 0;
        ft.totalDuration = duration > 0 ? duration : 1.0; 
        ft.cachedWidth = undefined; 

        this.damageNumbers.push(ft);
    }

    public breakCastText(ownerId: string) {
        const text = this.damageNumbers.find(t => t.type === 'SHOUT' && t.ownerId === ownerId && !t.isShattered);

        if (text) {
            text.isShattered = true;
            text.color = '#94a3b8'; 
            text.vy = -180; 
            text.vx = (Math.random() - 0.5) * 250; 
            text.vRot = (Math.random() - 0.5) * 20; 
            text.life = 0.5; 
            text.maxLife = 0.5;
        }
    }

    private release(ft: FloatingText) {
        ft.active = false;
        ft.ownerId = undefined;
        this.pool.push(ft);
    }

    public update(dt: number) {
        for (let i = this.damageNumbers.length - 1; i >= 0; i--) { 
            const d = this.damageNumbers[i]; 
            d.life -= dt; 
            d.time += dt;

            d.x += d.vx * dt;
            d.y += d.vy * dt; 
            d.rotation += d.vRot * dt; 

            if (d.type === 'DAMAGE' || d.type === 'HEAL' || d.isShattered) {
                const g = d.isShattered ? GRAVITY * 3.0 : GRAVITY;
                d.vy += g * dt;
            }
            else if (d.type === 'SHOUT' || d.type === 'CC') d.vy *= 0.95; 
            else if (d.type === 'KILL_STREAK') d.vy *= 0.92; 

            if (d.life <= 0) {
                this.release(d);
                this.damageNumbers.splice(i, 1); 
            }
        }
    }
}

import { GameEvent, GameEventType } from "../../../types";
import { GameEngine } from "../../game";
import { HUDSystem } from "../hud";
import { GridSystem } from "../grid";
import { CameraSystem } from "../CameraSystem";
import { HexUtils } from "../../utils";
import { HUD_TEXT_OFFSET } from "../../../constants";
import { STATUS_VISUALS } from "../../../data/vfx/status_visuals";

export class EventHUDMapper {

    public reset() {
        // No local state needed anymore
    }

    public process(
        event: GameEvent, 
        engine: GameEngine, 
        hud: HUDSystem, 
        grid: GridSystem,
        camera: CameraSystem
    ) {
        const hex = HexUtils.fromPx(event.pos.x, event.pos.y, engine.mapConfig);
        const terrainHeight = grid.getTerrainHeight(hex.q, hex.r, engine);
        const visualGroundY = event.pos.y - terrainHeight;

        switch (event.type) {
            case 'DAMAGE':
            case 'HEAL':
            case 'CC_APPLIED':
                this.handleCombatText(event, visualGroundY, hud);
                break;
            case 'CAST_START':
                this.handleCastText(event, visualGroundY, hud);
                break;
            case 'CAST_BREAK':
                // 核心：觸發文字崩解
                if (event.sourceId) {
                    hud.breakCastText(event.sourceId);
                    // 同時彈出 "中斷" 提示
                    const baseY = visualGroundY - HUD_TEXT_OFFSET;
                    hud.addFloatingText(event.pos.x, baseY, "INTERRUPTED", "#ef4444", 16, 'CC');
                }
                break;
            case 'KILL_STREAK':
                if (event.text && event.color) {
                    const textY = visualGroundY - HUD_TEXT_OFFSET - 40;
                    const size = 32 + ((event.value || 1) * 4); 
                    hud.addFloatingText(event.pos.x, textY, event.text, event.color, size, 'KILL_STREAK');
                    camera.addTrauma(0.2 + (event.value || 0) * 0.1);
                }
                break;
        }
    }

    private handleCombatText(event: GameEvent, visualY: number, hud: HUDSystem) {
        const baseY = visualY - HUD_TEXT_OFFSET; 
        let text = "";
        let color = "#fff";
        let size = 16;
        let type: 'DAMAGE' | 'HEAL' | 'CC' = 'DAMAGE';
        let xOffset = 0;

        if (event.type === 'DAMAGE') {
            const val = Math.abs(event.value || 0);
            text = val.toString();
            const isCrit = val > 100;
            const isDot = event.skill?.ccType === 'DOT';

            if (isDot) {
                color = STATUS_VISUALS['POISON']?.primaryColor || '#a3e635';
            } else if (isCrit) {
                color = '#ef4444'; 
            } else {
                color = '#fff';
            }

            size = isCrit ? 24 : 16;
            type = 'DAMAGE';
            xOffset = (Math.random() - 0.5) * 10;

        } else if (event.type === 'HEAL') {
            text = "+" + Math.abs(event.value || 0);
            color = STATUS_VISUALS['REGEN']?.primaryColor || '#4ade80';
            type = 'HEAL';
            xOffset = (Math.random() - 0.5) * 10;
        } else {
            text = event.text || "";
            color = event.color || "#fff";
            type = 'CC';
            size = 14;
            xOffset = -45;
        }

        if (text) hud.addFloatingText(event.pos.x + xOffset, baseY, text, color, size, type);
    }

    private handleCastText(event: GameEvent, visualY: number, hud: HUDSystem) {
        if (event.skill && event.skill.tag !== 'BASIC') {
            const isUlt = event.skill.tag === 'ULT';
            const baseY = visualY - HUD_TEXT_OFFSET - (isUlt ? 30 : 10); 
            const xOffset = 55; 
            // 綁定 sourceId 以便後續中斷，並傳入詠唱時間
            hud.addFloatingText(
                event.pos.x + xOffset, 
                baseY, 
                event.skill.name, 
                event.skill.color, 
                14, 
                'SHOUT', 
                isUlt,
                event.sourceId,
                event.skill.cast // 傳入詠唱時間
            );
        }
    }
}

import { HUDSystem } from "../../systems/hud";

export const TextPainter = {

    drawFloatingText(ctx: CanvasRenderingContext2D, hud: HUDSystem) {
        const textCount = hud.damageNumbers.length;
        if (textCount === 0) return;

        ctx.textAlign = 'center';
        ctx.textBaseline = 'middle';
        ctx.shadowBlur = 0; 

        hud.damageNumbers.forEach(d => {
            if (!d.active) return;

            const lifePct = d.life / d.maxLife;
            // Early cull for nearly invisible text
            if (lifePct <= 0.05) return;

            const alpha = d.isShattered ? lifePct : (lifePct < 0.3 ? lifePct / 0.3 : 1.0);
            ctx.globalAlpha = alpha;

            ctx.save();
            ctx.translate(d.x, d.y);

            if (d.rotation !== 0) ctx.rotate(d.rotation);

            if (d.isShattered) {
                const shatterProgress = 1 - lifePct;
                const scale = 1.0 + shatterProgress * 0.6;
                ctx.scale(scale, scale);
                ctx.translate((Math.random()-0.5)*4, (Math.random()-0.5)*4);
            } else if (d.type === 'SHOUT') {
                const floatY = Math.sin(d.time * 6) * 3;
                ctx.translate(0, floatY);
            }

            if (d.type === 'KILL_STREAK') {
                const pop = Math.min(1, (1 - lifePct) * 5); 
                const pulse = 1 + Math.sin(lifePct * 10) * 0.1;
                const scale = pop * pulse * 1.5; 
                ctx.scale(scale, scale);
                ctx.font = `900 italic ${d.size}px "Arial Black", sans-serif`;

                ctx.lineWidth = 4;
                ctx.lineJoin = 'round';
                ctx.strokeStyle = '#000';
                ctx.strokeText(d.text, 0, 0);
                ctx.fillStyle = d.color;
                ctx.fillText(d.text, 0, 0);

            } else if (d.type === 'SHOUT') {
                // [OPTIMIZATION] Cache Width
                if (d.cachedWidth === undefined) {
                    ctx.font = d.isUlt ? `900 italic ${d.size}px "Arial Black", sans-serif` : `bold ${d.size}px "Segoe UI", sans-serif`;
                    d.cachedWidth = ctx.measureText(d.text).width;
                }

                // 視覺參數：虛像化設計 (Holographic Design)
                const w = d.cachedWidth! + 20;
                const h = d.size + (d.isUlt ? 16 : 10);
                const halfW = w / 2;
                const halfH = h / 2;

                ctx.font = d.isUlt ? `900 italic ${d.size}px "Arial Black", sans-serif` : `bold ${d.size}px "Segoe UI", sans-serif`;

                if (d.isUlt) {
                    const scale = 1 + (1 - lifePct) * 0.1; 
                    ctx.scale(scale, scale);
                }

                if (d.isShattered) {
                    // 破碎狀態：灰色空殼
                    ctx.fillStyle = 'rgba(30, 30, 30, 0.6)'; 
                    ctx.fillRect(-halfW, -halfH, w, h);
                    ctx.strokeStyle = 'rgba(255,50,50,0.3)';
                    ctx.lineWidth = 1;
                    ctx.strokeRect(-halfW, -halfH, w, h);
                    ctx.fillStyle = '#94a3b8'; 
                    ctx.fillText(d.text, 0, 0);
                } else {
                    // --- 1. 繪製科技括號 (Tech Brackets) ---
                    // 不再繪製笨重的實心黑底，改用輕量級邊框
                    ctx.strokeStyle = d.color;
                    ctx.lineWidth = 1;
                    ctx.globalAlpha = 0.6;

                    const bracketSize = 6;
                    ctx.beginPath();
                    // 左括號 [
                    ctx.moveTo(-halfW + bracketSize, -halfH);
                    ctx.lineTo(-halfW, -halfH);
                    ctx.lineTo(-halfW, halfH);
                    ctx.lineTo(-halfW + bracketSize, halfH);
                    // 右括號 ]
                    ctx.moveTo(halfW - bracketSize, -halfH);
                    ctx.lineTo(halfW, -halfH);
                    ctx.lineTo(halfW, halfH);
                    ctx.lineTo(halfW - bracketSize, halfH);
                    ctx.stroke();

                    // --- 2. 繪製幽靈底字 (The Ghost) ---
                    // 代表未充能的部分，半透明
                    ctx.fillStyle = d.color;
                    ctx.globalAlpha = 0.2; // Dim
                    ctx.fillText(d.text, 0, 0);

                    // --- 3. 繪製實像填充 (The Fill) ---
                    // 使用 Clip Mask 模擬「文字被填滿」的效果，而非改變文字顏色
                    const progress = Math.min(1.0, d.time / d.totalDuration);

                    if (progress > 0.01) {
                        ctx.save();

                        // 定義裁切區域 (從左至右)
                        const revealW = w * progress;
                        ctx.beginPath();
                        ctx.rect(-halfW, -halfH, revealW, h);
                        ctx.clip();

                        // 繪製亮色文字 (Fully Opaque)
                        ctx.globalAlpha = 1.0;
                        ctx.fillStyle = '#ffffff'; // 核心亮白
                        // Ult 加光暈
                        if (d.isUlt) {
                            ctx.shadowColor = d.color;
                            ctx.shadowBlur = 8;
                        }
                        ctx.fillText(d.text, 0, 0);

                        // --- 4. 掃描線 (Scanner Line) ---
                        // 在裁切邊緣繪製一條高亮線，增加數據傳輸感
                        const scanX = -halfW + revealW;
                        ctx.shadowBlur = 5;
                        ctx.shadowColor = '#fff';
                        ctx.fillStyle = '#fff';
                        ctx.fillRect(scanX - 1, -halfH, 2, h);

                        ctx.restore();
                    }
                }

            } else {
                ctx.font = `900 ${d.size}px "Segoe UI", sans-serif`;
                ctx.lineWidth = 3;
                ctx.strokeStyle = 'rgba(0,0,0,0.8)';
                ctx.strokeText(d.text, 0, 0);
                ctx.fillStyle = d.color; 
                ctx.fillText(d.text, 0, 0);
            }

            ctx.restore();
            ctx.globalAlpha = 1.0;
        });
    }
};

const GRAVITY = 200;
const TEXT_LIFESPAN = 1.0;
const MAX_ACTIVE_TEXTS = 60; // Reduced for performance safety

export interface FloatingText {
    active: boolean;
    x: number; 
    y: number;
    vx: number; 
    vy: number;
    text: string; 
    color: string;
    life: number; 
    maxLife: number;
    size: number;
    type: 'DAMAGE' | 'HEAL' | 'SHOUT' | 'CC' | 'KILL_STREAK';
    isUlt: boolean; 

    // New Props for Breakable Text & Progress
    ownerId?: string;      // 用於綁定單位
    isShattered?: boolean; // 標記是否已被打斷
    rotation: number;      // 物理旋轉角度
    vRot: number;          // 旋轉速度

    // Animation Timer
    time: number;          // 存活時間 (累加)
    totalDuration: number; // 預計總詠唱時間 (用於進度條計算)
    cachedWidth?: number;  // Cached width for text measurement optimization
}

export class HUDSystem {
    public damageNumbers: FloatingText[] = [];
    private pool: FloatingText[] = [];

    constructor() {
        for(let i=0; i<50; i++) this.pool.push(this.createEmpty());
    }

    public reset() {
        for (const d of this.damageNumbers) this.release(d);
        this.damageNumbers.length = 0;
    }

    private createEmpty(): FloatingText {
        return {
            active: false,
            x: 0, y: 0, vx: 0, vy: 0,
            text: '', color: '#fff', life: 0, maxLife: 0, size: 0,
            type: 'DAMAGE', isUlt: false,
            ownerId: undefined, isShattered: false, rotation: 0, vRot: 0,
            time: 0, totalDuration: 0, cachedWidth: undefined
        };
    }

    public addFloatingText(
        x: number, y: number, text: string, color: string, size: number, 
        type: 'DAMAGE' | 'HEAL' | 'SHOUT' | 'CC' | 'KILL_STREAK' = 'DAMAGE', 
        isUlt: boolean = false,
        ownerId?: string,
        duration: number = 0
    ) {
        if (this.damageNumbers.length >= MAX_ACTIVE_TEXTS) {
            const old = this.damageNumbers.shift();
            if (old) this.release(old);
        }

        // Kill Streak 清理邏輯
        if (type === 'KILL_STREAK') {
            for (let i = this.damageNumbers.length - 1; i >= 0; i--) {
                if (this.damageNumbers[i].type === 'KILL_STREAK') {
                    this.release(this.damageNumbers[i]);
                    this.damageNumbers.splice(i, 1);
                }
            }
        }

        // 如果該單位已有存在的 SHOUT，先移除舊的 (避免重疊)
        if (type === 'SHOUT' && ownerId) {
            for (let i = this.damageNumbers.length - 1; i >= 0; i--) {
                const t = this.damageNumbers[i];
                if (t.type === 'SHOUT' && t.ownerId === ownerId && !t.isShattered) {
                    this.release(t);
                    this.damageNumbers.splice(i, 1);
                }
            }
        }

        let vx = 0, vy = 0, life = TEXT_LIFESPAN;
        if (type === 'SHOUT') {
            // SHOUT 的生命週期現在由詠唱時間決定
            const safeDuration = Math.min(5.0, duration > 0 ? duration : 1.0);
            life = safeDuration + 0.5;
            if (isUlt) { vy = -5; size = 24; }
            else { vy = -20; size = 14; }
        } else if (type === 'CC') {
            vy = -20; life = 1.5;
        } else if (type === 'KILL_STREAK') {
            vx = 0; vy = -30; life = 3.5; size = 32; 
        } else {
            vx = (Math.random() - 0.5) * 60; vy = -100; 
        }

        let ft = this.pool.length > 0 ? this.pool.pop()! : this.createEmpty();
        ft.active = true;
        ft.x = x; ft.y = y; ft.vx = vx; ft.vy = vy;
        ft.text = text; ft.color = color;
        ft.life = life; ft.maxLife = life;
        ft.size = size; ft.type = type;
        ft.isUlt = isUlt;
        ft.ownerId = ownerId;
        ft.isShattered = false;
        ft.rotation = 0;
        ft.vRot = 0;
        ft.time = 0;
        ft.totalDuration = duration > 0 ? duration : 1.0; 
        ft.cachedWidth = undefined; 

        this.damageNumbers.push(ft);
    }

    /**
     * 強制中斷文字：給予極高的向上速度與旋轉，並縮短壽命
     * 創造出 "文字被打飛/震碎" 的視覺效果
     */
    public breakCastText(ownerId: string) {
        const text = this.damageNumbers.find(t => t.type === 'SHOUT' && t.ownerId === ownerId && !t.isShattered);

        if (text) {
            text.isShattered = true;
            text.color = '#94a3b8'; // 變成灰色廢墟感
            text.vy = -250; // 用力向上炸飛
            text.vx = (Math.random() - 0.5) * 400; // 隨機左右噴飛
            text.vRot = (Math.random() - 0.5) * 30; // 劇烈旋轉
            text.life = 0.4; // 快速消失
            text.maxLife = 0.4;
        }
    }

    private release(ft: FloatingText) {
        ft.active = false;
        ft.ownerId = undefined;
        this.pool.push(ft);
    }

    public update(dt: number) {
        for (let i = this.damageNumbers.length - 1; i >= 0; i--) { 
            const d = this.damageNumbers[i]; 
            d.life -= dt; 
            d.time += dt;

            d.x += d.vx * dt;
            d.y += d.vy * dt; 
            d.rotation += d.vRot * dt; 

            if (d.type === 'DAMAGE' || d.type === 'HEAL' || d.isShattered) {
                const g = d.isShattered ? GRAVITY * 4.0 : GRAVITY; // 碎片重力更強
                d.vy += g * dt;
            }
            else if (d.type === 'SHOUT' || d.type === 'CC') d.vy *= 0.95; 
            else if (d.type === 'KILL_STREAK') d.vy *= 0.92; 

            if (d.life <= 0) {
                this.release(d);
                this.damageNumbers.splice(i, 1); 
            }
        }
    }
}

import { GameEvent, GameEventType } from "../../../types";
import { GameEngine } from "../../game";
import { HUDSystem } from "../hud";
import { GridSystem } from "../grid";
import { CameraSystem } from "../CameraSystem";
import { HexUtils } from "../../utils";
import { HUD_TEXT_OFFSET } from "../../../constants";
import { STATUS_VISUALS } from "../../../data/vfx/status_visuals";

export class EventHUDMapper {

    public reset() {
        // No local state needed anymore
    }

    public process(
        event: GameEvent, 
        engine: GameEngine, 
        hud: HUDSystem, 
        grid: GridSystem,
        camera: CameraSystem
    ) {
        const hex = HexUtils.fromPx(event.pos.x, event.pos.y, engine.mapConfig);
        const terrainHeight = grid.getTerrainHeight(hex.q, hex.r, engine);
        const visualGroundY = event.pos.y - terrainHeight;

        switch (event.type) {
            case 'DAMAGE':
            case 'HEAL':
            case 'CC_APPLIED':
                this.handleCombatText(event, visualGroundY, hud);
                break;
            case 'CAST_START':
                this.handleCastText(event, visualGroundY, hud);
                break;
            case 'CAST_BREAK':
                // 核心：觸發文字崩解，瞬間移除詠唱條
                if (event.sourceId) {
                    hud.breakCastText(event.sourceId);
                    // 同時彈出 "中斷" 提示
                    const baseY = visualGroundY - HUD_TEXT_OFFSET;
                    hud.addFloatingText(event.pos.x, baseY, "INTERRUPTED", "#ef4444", 16, 'CC');
                }
                break;
            case 'KILL_STREAK':
                if (event.text && event.color) {
                    const textY = visualGroundY - HUD_TEXT_OFFSET - 40;
                    const size = 32 + ((event.value || 1) * 4); 
                    hud.addFloatingText(event.pos.x, textY, event.text, event.color, size, 'KILL_STREAK');
                    camera.addTrauma(0.2 + (event.value || 0) * 0.1);
                }
                break;
        }
    }

    private handleCombatText(event: GameEvent, visualY: number, hud: HUDSystem) {
        const baseY = visualY - HUD_TEXT_OFFSET; 
        let text = "";
        let color = "#fff";
        let size = 16;
        let type: 'DAMAGE' | 'HEAL' | 'CC' = 'DAMAGE';
        let xOffset = 0;

        if (event.type === 'DAMAGE') {
            const val = Math.abs(event.value || 0);
            text = val.toString();
            const isCrit = val > 100;
            const isDot = event.skill?.ccType === 'DOT';

            if (isDot) {
                color = STATUS_VISUALS['POISON']?.primaryColor || '#a3e635';
            } else if (isCrit) {
                color = '#ef4444'; 
            } else {
                color = '#fff';
            }

            size = isCrit ? 24 : 16;
            type = 'DAMAGE';
            xOffset = (Math.random() - 0.5) * 10;

        } else if (event.type === 'HEAL') {
            text = "+" + Math.abs(event.value || 0);
            color = STATUS_VISUALS['REGEN']?.primaryColor || '#4ade80';
            type = 'HEAL';
            xOffset = (Math.random() - 0.5) * 10;
        } else {
            text = event.text || "";
            color = event.color || "#fff";
            type = 'CC';
            size = 14;
            xOffset = -45;
        }

        if (text) hud.addFloatingText(event.pos.x + xOffset, baseY, text, color, size, type);
    }

    private handleCastText(event: GameEvent, visualY: number, hud: HUDSystem) {
        if (event.skill && event.skill.tag !== 'BASIC') {
            const isUlt = event.skill.tag === 'ULT';
            const baseY = visualY - HUD_TEXT_OFFSET - (isUlt ? 30 : 10); 
            const xOffset = 55; 
            // 綁定 sourceId 以便後續中斷，並傳入詠唱時間
            hud.addFloatingText(
                event.pos.x + xOffset, 
                baseY, 
                event.skill.name, 
                event.skill.color, 
                14, 
                'SHOUT', 
                isUlt,
                event.sourceId,
                event.skill.cast // 傳入詠唱時間
            );
        }
    }
}

